window.SHCD_DATA = {"generatedAt":"2026-10-18","total":128,"subjects":[{"id":"quyche","name":"Quy chế đào tạo","title":"Quy chế đào tạo theo tín chỉ","eyebrow":"Bộ đề 01","description":"48 câu hỏi trắc nghiệm và đúng/sai về quy chế đào tạo theo tín chỉ, kèm đáp án và căn cứ điều khoản.","pdf":"assets/Dap_an_Quy_che_dao_tao.pdf","source":"b_c_u_h_i_n_t_p_quy_ch_o_t_o_t_n_ch.md","count":48,"questions":[{"id":1,"type":"multiple_choice","question":"Thời gian đào tạo tối đa của chương trình đại học chính quy của sinh viên nhập học từ năm 2025 trở về trước (trừ ngành bác sĩ thú y và các chương trình tiên tiến) là bao nhiêu năm?","options":[{"key":"a","label":"A","text":"7,0 năm","correct":false},{"key":"b","label":"B","text":"6,0 năm","correct":false},{"key":"c","label":"C","text":"5,0 năm","correct":false},{"key":"d","label":"D","text":"8,0 năm","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"8,0 năm","explanation":"Theo Điều 2 Khoản 7, thời gian tối đa đối với các ngành đại học chính quy khóa tuyển sinh 2025 trở về trước là 8,0 năm."},{"id":2,"type":"multiple_choice","question":"Theo Quy chế, sinh viên vượt quá thời gian học tập tối đa sẽ bị xử lý như thế nào?","options":[{"key":"a","label":"A","text":"Bị buộc thôi học","correct":true},{"key":"b","label":"B","text":"Được tự động gia hạn thêm 3 năm","correct":false},{"key":"c","label":"C","text":"Hạ 1 bậc xếp loại bằng","correct":false},{"key":"d","label":"D","text":"Bị cảnh báo học tập","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Bị buộc thôi học","explanation":"Theo Điều 18 Khoản 2 Điểm c, thời gian học tập vượt quá giới hạn sẽ bị buộc thôi học."},{"id":3,"type":"multiple_choice","question":"Học phần bắt buộc được hiểu là học phần như thế nào?","options":[{"key":"a","label":"A","text":"Không thuộc chương trình đào tạo","correct":false},{"key":"b","label":"B","text":"Sinh viên được tự chọn theo sở thích","correct":false},{"key":"c","label":"C","text":"Học phần bắt buộc phải tích lũy theo chương trình đào tạo","correct":true},{"key":"d","label":"D","text":"Là học phần sinh viên phải hoàn thành nhưng kết quả không dùng để tính trung bình chung tích lũy","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Học phần bắt buộc phải tích lũy theo chương trình đào tạo","explanation":"Theo Điều 4 Khoản 1 Điểm a, học phần bắt buộc chứa đựng kiến thức chính yếu và bắt buộc sinh viên phải tích lũy."},{"id":4,"type":"multiple_choice","question":"Học phần tự chọn được hiểu như thế nào?","options":[{"key":"a","label":"A","text":"Bắt buộc phải học đúng một môn xác định","correct":false},{"key":"b","label":"B","text":"Không được tính trong chương trình đào tạo","correct":false},{"key":"c","label":"C","text":"Sinh viên chọn theo hướng dẫn của chương trình đào tạo","correct":true},{"key":"d","label":"D","text":"Chỉ dành cho sinh viên năm cuối","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Sinh viên chọn theo hướng dẫn của chương trình đào tạo","explanation":"Theo Điều 4 Khoản 1 Điểm b, sinh viên được tự chọn theo hướng dẫn nhằm đa dạng hóa hướng chuyên môn."},{"id":5,"type":"multiple_choice","question":"Nếu học phần A là học phần tiên quyết của học phần B, trước khi đăng ký học phần B, sinh viên phải đáp ứng điều kiện nào đối với học phần A?","options":[{"key":"a","label":"A","text":"Đã đăng ký thành công và thanh toán học phí cho A","correct":false},{"key":"b","label":"B","text":"Đã học A nhưng không cần đạt","correct":false},{"key":"c","label":"C","text":"Đã đăng ký thành công học phần A","correct":false},{"key":"d","label":"D","text":"Đã học và đạt A","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Đã học và đạt A","explanation":"Theo Điều 4 Khoản 1 Điểm c, muốn đăng ký học phần B bắt buộc trước đó phải đạt học phần A."},{"id":6,"type":"multiple_choice","question":"Đối với học phần song hành, sinh viên phải thực hiện như thế nào?","options":[{"key":"a","label":"A","text":"Chỉ cần dự thi môn còn lại","correct":false},{"key":"b","label":"B","text":"Chỉ đăng ký sau khi đạt môn còn lại","correct":false},{"key":"c","label":"C","text":"Đăng ký đồng thời trong cùng một học kỳ ở lần học đầu tiên","correct":true},{"key":"d","label":"D","text":"Học ở hai học kỳ khác nhau","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Đăng ký đồng thời trong cùng một học kỳ ở lần học đầu tiên","explanation":"Theo Điều 4 Khoản 1 Điểm e, học phần song hành phải đăng ký học đồng thời trong cùng học kỳ ở lần học đầu tiên."},{"id":7,"type":"multiple_choice","question":"A là học phần học trước của B, điều kiện để đăng ký B là gì?","options":[{"key":"a","label":"A","text":"Đã học và phải đạt A","correct":false},{"key":"b","label":"B","text":"Đã đăng ký học và dự thi A, không bắt buộc đạt","correct":true},{"key":"c","label":"C","text":"Phải đạt điểm tối thiểu 5,5 ở học phần A","correct":false},{"key":"d","label":"D","text":"Đã hoàn thành học phần B","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Đã đăng ký học và dự thi A, không bắt buộc đạt","explanation":"Theo Điều 4 Khoản 1 Điểm d, học phần học trước chỉ yêu cầu đã học và dự thi kết thúc học phần A (không nhất thiết phải đạt)."},{"id":8,"type":"multiple_choice","question":"Học phần cốt lõi (Assessed - A) được xem là đạt khi điểm học phần tối thiểu là mức nào?","options":[{"key":"a","label":"A","text":"≥ 5,5/10 hoặc ≥ 2,0/4","correct":true},{"key":"b","label":"B","text":"≥ 4,0/10 hoặc ≥ 1,0/4","correct":false},{"key":"c","label":"C","text":"≥ 5,0/10 hoặc ≥ 1,5/4","correct":false},{"key":"d","label":"D","text":"≥ 6,5/10 hoặc ≥ 2,5/4","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"≥ 5,5/10 hoặc ≥ 2,0/4","explanation":"Theo Điều 4 Khoản 1 Điểm i và Điều 13 Khoản 3 Điểm a, điểm đạt của học phần cốt lõi là ≥ 5,5 thang 10 hoặc ≥ 2,0 (điểm C) thang 4."},{"id":9,"type":"multiple_choice","question":"Sinh viên không đăng ký học phần trong bao nhiêu học kỳ liên tiếp thì có thể bị buộc thôi học?","options":[{"key":"a","label":"A","text":"4 học kỳ","correct":false},{"key":"b","label":"B","text":"5 học kỳ","correct":false},{"key":"c","label":"C","text":"3 học kỳ","correct":true},{"key":"d","label":"D","text":"2 học kỳ","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"3 học kỳ","explanation":"Theo Điều 9 Khoản 4 Điểm a, không đăng ký bất kỳ học phần nào trong 03 học kỳ liên tiếp được xác định tự ý bỏ học và bị buộc thôi học."},{"id":10,"type":"multiple_choice","question":"Theo Quy chế, khối lượng học tập tối đa sinh viên được đăng ký trong một học kỳ không vượt quá mức nào?","options":[{"key":"a","label":"A","text":"3/2 khối lượng trung bình của một học kỳ","correct":true},{"key":"b","label":"B","text":"1/2 khối lượng trung bình của một học kỳ","correct":false},{"key":"c","label":"C","text":"2 lần khối lượng trung bình của một học kỳ","correct":false},{"key":"d","label":"D","text":"2/3 khối lượng trung bình của một học kỳ","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"3/2 khối lượng trung bình của một học kỳ","explanation":"Theo Điều 9 Khoản 3 Điểm b, khối lượng tối đa không vượt quá 3/2 khối lượng trung bình một học kỳ theo kế hoạch chuẩn."},{"id":11,"type":"multiple_choice","question":"Sĩ số tối thiểu của lớp lý thuyết hoặc lý thuyết kết hợp thực hành là bao nhiêu sinh viên?","options":[{"key":"a","label":"A","text":"20","correct":false},{"key":"b","label":"B","text":"40","correct":false},{"key":"c","label":"C","text":"25","correct":false},{"key":"d","label":"D","text":"30","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"30","explanation":"Theo Điều 10 Khoản 1, lớp lý thuyết hoặc lý thuyết kết hợp thực hành có số lượng tối thiểu là 30 sinh viên."},{"id":12,"type":"multiple_choice","question":"Học phần tương đương được hiểu là học phần nào?","options":[{"key":"a","label":"A","text":"Môn của khóa khác bất kỳ","correct":false},{"key":"b","label":"B","text":"Học phần được xác định tương đương về nội dung và khối lượng để thay cho học phần yêu cầu","correct":true},{"key":"c","label":"C","text":"Môn có điểm cao hơn","correct":false},{"key":"d","label":"D","text":"Môn có tên giống nhau","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Học phần được xác định tương đương về nội dung và khối lượng để thay cho học phần yêu cầu","explanation":"Theo Điều 4 Khoản 1 Điểm g, học phần tương đương có nội dung và khối lượng kiến thức tương đương để thay cho học phần trong CTĐT."},{"id":13,"type":"multiple_choice","question":"Học phần thay thế được áp dụng trong trường hợp nào?","options":[{"key":"a","label":"A","text":"Khi học phần cũ không còn tổ chức giảng dạy","correct":true},{"key":"b","label":"B","text":"Khi sinh viên muốn đổi môn","correct":false},{"key":"c","label":"C","text":"Khi sinh viên muốn rút học phần","correct":false},{"key":"d","label":"D","text":"Khi điểm học phần cũ thấp","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Khi học phần cũ không còn tổ chức giảng dạy","explanation":"Theo Điều 4 Khoản 1 Điểm h, học phần thay thế dùng thay thế cho một học phần có trong CTĐT nhưng nay không còn tổ chức giảng dạy."},{"id":14,"type":"multiple_choice","question":"Để được dự thi kết thúc học phần lý thuyết, sinh viên phải tham dự tối thiểu bao nhiêu phần trăm số giờ?","options":[{"key":"a","label":"A","text":"80%","correct":true},{"key":"b","label":"B","text":"50%","correct":false},{"key":"c","label":"C","text":"70%","correct":false},{"key":"d","label":"D","text":"100%","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"80%","explanation":"Theo Điều 10 Khoản 4 Điểm c, sinh viên phải tham dự tối thiểu 80% số giờ đối với các học phần lý thuyết."},{"id":15,"type":"multiple_choice","question":"Đối với học phần thực hành, thí nghiệm, thực tập, sinh viên phải tham dự ở mức nào?","options":[{"key":"a","label":"A","text":"Ít nhất 70%","correct":false},{"key":"b","label":"B","text":"Ít nhất 80%","correct":false},{"key":"c","label":"C","text":"Ít nhất 50%","correct":false},{"key":"d","label":"D","text":"Đầy đủ 100%","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Đầy đủ 100%","explanation":"Theo Điều 10 Khoản 4 Điểm c, tham dự đầy đủ 100% số giờ đối với thực hành, thí nghiệm, thực tập."},{"id":16,"type":"multiple_choice","question":"Sinh viên vắng quá quy định về tham dự học phần sẽ bị xử lý như thế nào?","options":[{"key":"a","label":"A","text":"Nhận điểm R","correct":false},{"key":"b","label":"B","text":"Bị trừ điểm rèn luyện","correct":false},{"key":"c","label":"C","text":"Được tự động nhận điểm I","correct":false},{"key":"d","label":"D","text":"Bị cấm thi","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Bị cấm thi","explanation":"Theo Điều 10 Khoản 4 Điểm c, sinh viên vắng nhiều hơn thời gian quy định sẽ bị cấm thi (nhận điểm F)."},{"id":17,"type":"multiple_choice","question":"Sinh viên vắng thi kết thúc học phần không có lý do chính đáng sẽ nhận kết quả nào?","options":[{"key":"a","label":"A","text":"Được thi ở kỳ gần nhất","correct":false},{"key":"b","label":"B","text":"Điểm F","correct":true},{"key":"c","label":"C","text":"Điểm I","correct":false},{"key":"d","label":"D","text":"Điểm R","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Điểm F","explanation":"Theo Điều 12 Khoản 4, vắng mặt không có lý do chính đáng phải nhận điểm F."},{"id":18,"type":"multiple_choice","question":"Sinh viên vắng thi có lý do chính đáng và được chấp thuận sẽ được ghi nhận ký hiệu nào?","options":[{"key":"a","label":"A","text":"M","correct":false},{"key":"b","label":"B","text":"R","correct":false},{"key":"c","label":"C","text":"I","correct":true},{"key":"d","label":"D","text":"X","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"I","explanation":"Theo Điều 12 Khoản 4 và Điều 13 Khoản 3 Điểm c, có lý do chính đáng được hoãn thi và hưởng điểm I."},{"id":19,"type":"multiple_choice","question":"Nếu quá thời hạn hoàn thiện điểm I theo Quy chế, điểm I sẽ được xử lý như thế nào?","options":[{"key":"a","label":"A","text":"Chuyển thành F","correct":true},{"key":"b","label":"B","text":"Chuyển thành A","correct":false},{"key":"c","label":"C","text":"Chuyển thành C","correct":false},{"key":"d","label":"D","text":"Giữ nguyên I không thời hạn","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Chuyển thành F","explanation":"Theo Điều 13 Khoản 3 Điểm c, quá thời hạn nếu không hoàn thành sẽ bị điểm F."},{"id":20,"type":"multiple_choice","question":"Điểm 8,5-10,0 theo thang điểm 10 tương ứng với điểm chữ nào?","options":[{"key":"a","label":"A","text":"A","correct":true},{"key":"b","label":"B","text":"B","correct":false},{"key":"c","label":"C","text":"C+","correct":false},{"key":"d","label":"D","text":"B+","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"A","explanation":"Theo bảng quy đổi điểm tại Điều 13 Khoản 3 Điểm a, thang điểm 8,5 - 10,0 tương ứng với điểm chữ A."},{"id":21,"type":"multiple_choice","question":"Điểm 6,5-6,9 theo thang điểm 10 tương ứng với điểm chữ nào?","options":[{"key":"a","label":"A","text":"C+","correct":true},{"key":"b","label":"B","text":"B","correct":false},{"key":"c","label":"C","text":"B+","correct":false},{"key":"d","label":"D","text":"C","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"C+","explanation":"Theo bảng quy đổi điểm tại Điều 13 Khoản 3 Điểm a, thang điểm 6,5 - 6,9 quy đổi thành điểm chữ C+ (2,5 hệ 4)."},{"id":22,"type":"multiple_choice","question":"Điểm 5,5-6,4 theo thang điểm 10 tương ứng với điểm chữ nào?","options":[{"key":"a","label":"A","text":"C","correct":true},{"key":"b","label":"B","text":"F","correct":false},{"key":"c","label":"C","text":"D","correct":false},{"key":"d","label":"D","text":"D+","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"C","explanation":"Theo Điều 13 Khoản 3 Điểm a, khoảng điểm 5,5 - 6,4 tương ứng với điểm chữ C (2,0 hệ 4)."},{"id":23,"type":"multiple_choice","question":"Ký hiệu I trong kết quả học tập được hiểu là gì?","options":[{"key":"a","label":"A","text":"Rút học phần hợp lệ","correct":false},{"key":"b","label":"B","text":"Chưa hoàn thiện","correct":true},{"key":"c","label":"C","text":"Chưa đủ dữ liệu","correct":false},{"key":"d","label":"D","text":"Được miễn học","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Chưa hoàn thiện","explanation":"Theo Điều 13 Khoản 3 Điểm c, chữ I là điểm chưa hoàn thiện do được hoãn thi/kiểm tra có lý do chính đáng."},{"id":24,"type":"multiple_choice","question":"Ký hiệu R trong kết quả học tập được hiểu là gì?","options":[{"key":"a","label":"A","text":"Đạt không phản ánh điểm","correct":false},{"key":"b","label":"B","text":"Chưa hoàn thiện","correct":false},{"key":"c","label":"C","text":"Được miễn học","correct":false},{"key":"d","label":"D","text":"Rút học phần hợp lệ","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Rút học phần hợp lệ","explanation":"Theo Điều 13 Khoản 3 Điểm c, điểm R dành cho các học phần sinh viên được phép rút hợp lệ."},{"id":25,"type":"multiple_choice","question":"Điểm trung bình chung học kỳ được tính theo nguyên tắc nào?","options":[{"key":"a","label":"A","text":"Tổng điểm hệ 10 chia số tín chỉ","correct":false},{"key":"b","label":"B","text":"Điểm học tập + điểm rèn luyện quy đổi","correct":false},{"key":"c","label":"C","text":"Tổng (tín chỉ × điểm quy đổi hệ 4) chia tổng số tín chỉ tương ứng","correct":true},{"key":"d","label":"D","text":"Tổng điểm hệ 4 chia số tín chỉ","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Tổng (tín chỉ × điểm quy đổi hệ 4) chia tổng số tín chỉ tương ứng","explanation":"Theo công thức tính ĐTBCHK tại Điều 15 Khoản 1 Điểm b: ĐTBCHK = tổng (ai * Xi) / tổng ai trên hệ điểm 4."},{"id":26,"type":"multiple_choice","question":"ĐTBCHK (điểm trung bình chung học kỳ) được tính cho những học phần nào?","options":[{"key":"a","label":"A","text":"Các học phần có điểm trong học kỳ, kể cả điểm F","correct":true},{"key":"b","label":"B","text":"Chỉ những học phần đạt","correct":false},{"key":"c","label":"C","text":"Chỉ học phần cốt lõi và học phần tự chọn có điểm >4,0","correct":false},{"key":"d","label":"D","text":"Chỉ học phần cốt lõi và học phần tự chọn có điểm >5,5","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Các học phần có điểm trong học kỳ, kể cả điểm F","explanation":"Theo Điều 15 Khoản 1 Điểm b, ĐTBCHK tính cho các học phần mà sinh viên đã học trong học kỳ (kể cả các học phần có điểm không đạt F)."},{"id":27,"type":"multiple_choice","question":"Điểm trung bình chung năm học được xác định như thế nào?","options":[{"key":"a","label":"A","text":"Trung bình cộng của tất cả các môn trong năm","correct":false},{"key":"b","label":"B","text":"Trung bình cộng của 2 học kỳ","correct":false},{"key":"c","label":"C","text":"Trung bình cộng của 03 học kỳ trong năm","correct":true},{"key":"d","label":"D","text":"Tổng (tín chỉ x điểm quy đổi hệ 4) chia tổng số tín chỉ trong năm","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Trung bình cộng của 03 học kỳ trong năm","explanation":"Theo Điều 15 Khoản 1 Điểm b, ĐTBCNH được xác định bằng trung bình cộng của 03 học kỳ trong năm học."},{"id":28,"type":"multiple_choice","question":"Điểm trung bình chung tích lũy được sử dụng chủ yếu để làm gì?","options":[{"key":"a","label":"A","text":"Xét học bổng","correct":false},{"key":"b","label":"B","text":"Xét điều kiện làm luận văn tốt nghiệp","correct":false},{"key":"c","label":"C","text":"Tính điểm rèn luyện","correct":false},{"key":"d","label":"D","text":"Xét tốt nghiệp và xếp loại bằng","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Xét tốt nghiệp và xếp loại bằng","explanation":"Theo Điều 15 Khoản 1 Điểm b và Slide 23, ĐTBCTL là cơ sở để xếp loại học lực, xét tốt nghiệp và xếp loại bằng."},{"id":29,"type":"multiple_choice","question":"Khi sinh viên học lại một học phần, điểm nào được sử dụng để tính Điểm trung bình chung tích lũy?","options":[{"key":"a","label":"A","text":"Chỉ điểm lần đầu","correct":false},{"key":"b","label":"B","text":"Điểm cao nhất","correct":true},{"key":"c","label":"C","text":"Trung bình của các lần học","correct":false},{"key":"d","label":"D","text":"Điểm học lại","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Điểm cao nhất","explanation":"Theo Điều 9 Khoản 8 Điểm b và Slide 23, điểm chính thức của học phần được tính vào tích lũy là điểm cao nhất trong các lần học."},{"id":30,"type":"multiple_choice","question":"Trong học kỳ đầu tiên của khóa học, sinh viên bị cảnh báo học tập khi ĐTBCHK dưới mức nào?","options":[{"key":"a","label":"A","text":"1,0","correct":false},{"key":"b","label":"B","text":"0,8","correct":true},{"key":"c","label":"C","text":"1,5","correct":false},{"key":"d","label":"D","text":"2,0","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"0,8","explanation":"Theo Điều 18 Khoản 1, cảnh báo học tập nếu ĐTBCHK dưới 0,8 đối với học kỳ đầu của khóa học."},{"id":31,"type":"multiple_choice","question":"Từ học kỳ thứ hai của khóa học trở đi, sinh viên bị cảnh báo học tập khi ĐTBCHK dưới mức nào?","options":[{"key":"a","label":"A","text":"2,0","correct":false},{"key":"b","label":"B","text":"1,0","correct":true},{"key":"c","label":"C","text":"1,5","correct":false},{"key":"d","label":"D","text":"0,8","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"1,0","explanation":"Theo Điều 18 Khoản 1, dưới 1,0 đối với các học kỳ tiếp theo."},{"id":32,"type":"multiple_choice","question":"Trường hợp nào dưới đây là một căn cứ buộc thôi học theo Quy chế?","options":[{"key":"a","label":"A","text":"Bị cảnh báo học tập quá 02 lần liên tiếp","correct":true},{"key":"b","label":"B","text":"Đăng ký ít học phần trong 02 học kỳ liên tiếp","correct":false},{"key":"c","label":"C","text":"Có 01 học phần cốt lõi không đạt","correct":false},{"key":"d","label":"D","text":"Bị cảnh báo học tập đúng 02 lần","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Bị cảnh báo học tập quá 02 lần liên tiếp","explanation":"Theo Điều 18 Khoản 2 Điểm b, sinh viên bị buộc thôi học khi bị cảnh báo kết quả học tập quá 02 lần liên tiếp."},{"id":33,"type":"multiple_choice","question":"Để nghỉ học tạm thời vì lý do cá nhân, sinh viên phải đáp ứng điều kiện nào?","options":[{"key":"a","label":"A","text":"Chỉ cần là sinh viên năm nhất","correct":false},{"key":"b","label":"B","text":"Điểm trung bình chung học kỳ ≥ 2,0","correct":false},{"key":"c","label":"C","text":"Không cần điều kiện","correct":false},{"key":"d","label":"D","text":"Học xong ít nhất 1 học kỳ và ĐTBCTL ≥ 2,00","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Học xong ít nhất 1 học kỳ và ĐTBCTL ≥ 2,00","explanation":"Theo Điều 21 Khoản 1 Điểm d, nghỉ vì lý do cá nhân phải học xong tối thiểu 01 học kỳ và đạt ĐTBCTL không dưới 2,00."},{"id":34,"type":"multiple_choice","question":"Nghỉ học tạm thời vì lý do cá nhân được giới hạn tối đa bao nhiêu học kỳ liên tiếp?","options":[{"key":"a","label":"A","text":"1","correct":false},{"key":"b","label":"B","text":"2","correct":false},{"key":"c","label":"C","text":"4","correct":false},{"key":"d","label":"D","text":"3","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"3","explanation":"Theo Điều 21 Khoản 2, không vượt quá 03 học kỳ liên tiếp."},{"id":35,"type":"multiple_choice","question":"Nếu muốn chuyển ngành, ngoài những điều kiện khác, điểm trúng tuyển của sinh viên phải đáp ứng yêu cầu nào?","options":[{"key":"a","label":"A","text":"Cao hơn 15 điểm","correct":false},{"key":"b","label":"B","text":"Cao hơn điểm chuẩn của ngành chuyển đến tối thiểu 2 điểm","correct":false},{"key":"c","label":"C","text":"Đạt điểm đảm bảo chất lượng đầu vào (điểm sàn) ngành chuyển đến","correct":false},{"key":"d","label":"D","text":"Không thấp hơn điểm chuẩn của ngành muốn chuyển đến","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Không thấp hơn điểm chuẩn của ngành muốn chuyển đến","explanation":"Theo Điều 22 Khoản 1 Điểm b và Slide 25, điểm trúng tuyển phải đạt điều kiện trúng tuyển (≥ điểm chuẩn) của ngành muốn chuyển đến."},{"id":36,"type":"multiple_choice","question":"Khi học cùng lúc 2 chương trình, thời gian tối đa được tính theo chương trình nào?","options":[{"key":"a","label":"A","text":"Chương trình thứ nhất","correct":true},{"key":"b","label":"B","text":"Chương trình thứ hai","correct":false},{"key":"c","label":"C","text":"Chương trình có ĐTBCTL cao hơn","correct":false},{"key":"d","label":"D","text":"Chương trình thứ nhất + 2 năm","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Chương trình thứ nhất","explanation":"Theo Điều 24 Khoản 5, thời gian tối đa được phép học tính theo thời gian tối đa quy định cho chương trình thứ nhất."},{"id":37,"type":"multiple_choice","question":"Điều kiện để được học cùng lúc 2 chương trình là gì?","options":[{"key":"a","label":"A","text":"Đã đạt ít nhất 100 tín chỉ","correct":false},{"key":"b","label":"B","text":"Đang là sinh viên năm nhất","correct":false},{"key":"c","label":"C","text":"ĐTBCTL đạt Khá trở lên; hoặc ĐTBCTL đạt Trung bình và đáp ứng điều kiện trúng tuyển ngành thứ hai","correct":true},{"key":"d","label":"D","text":"Chưa từng rớt môn cốt lõi","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"ĐTBCTL đạt Khá trở lên; hoặc ĐTBCTL đạt Trung bình và đáp ứng điều kiện trúng tuyển ngành thứ hai","explanation":"Theo Điều 24 Khoản 2 Điểm a, học lực tích lũy loại Khá trở lên hoặc loại Trung bình kèm đáp ứng điều kiện trúng tuyển của ngành 2."},{"id":38,"type":"multiple_choice","question":"Một điều kiện về khối lượng học tập để xét học bổng khuyến khích học tập là gì?","options":[{"key":"a","label":"A","text":"Đăng ký ≥ 3/4 khối lượng chuẩn","correct":false},{"key":"b","label":"B","text":"Đăng ký ≥ 1/2 khối lượng chuẩn","correct":false},{"key":"c","label":"C","text":"Đăng ký ≥ 2/3 khối lượng chuẩn của học kỳ","correct":true},{"key":"d","label":"D","text":"Đăng ký học phần bằng khối lượng chuẩn của học kỳ","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Đăng ký ≥ 2/3 khối lượng chuẩn của học kỳ","explanation":"Theo Điều 26 Khoản 1 Điểm b, sinh viên phải đăng ký khối lượng học tập tối thiểu bằng 2/3 khối lượng trung bình một học kỳ theo kế hoạch chuẩn."},{"id":39,"type":"multiple_choice","question":"Trường hợp nào có thể làm sinh viên bị hạ một bậc xếp loại bằng?","options":[{"key":"a","label":"A","text":"Từng rớt môn học cốt lõi","correct":false},{"key":"b","label":"B","text":"Đăng ký dưới 10 tín chỉ trong 3 học kỳ","correct":false},{"key":"c","label":"C","text":"Tổng số tín chỉ các môn đã rút nhiều hơn 5% tổng số tín chỉ","correct":false},{"key":"d","label":"D","text":"Có học phần F chiếm hơn 5% tổng số tín chỉ quy định hoặc từng bị kỷ luật mức cảnh cáo","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Có học phần F chiếm hơn 5% tổng số tín chỉ quy định hoặc từng bị kỷ luật mức cảnh cáo","explanation":"Theo Điều 20 Khoản 7 Điểm c, hạng tốt nghiệp loại Xuất sắc và Giỏi bị giảm một mức nếu khối lượng học phần học lại > 5% tổng số tín chỉ hoặc bị kỷ luật từ mức cảnh cáo trở lên."},{"id":40,"type":"true_false","question":"Học phần tiên quyết yêu cầu sinh viên phải học và đạt học phần A trước khi đăng ký học phần B.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":true},{"key":"false","label":"S","text":"Sai","correct":false}],"answerKey":"true","answerLabel":"Đúng","keyLabel":"Đ","answerText":"Đúng","explanation":"Theo Điều 4 Khoản 1 Điểm c, học phần tiên quyết bắt buộc sinh viên phải học và đạt học phần A trước khi đăng ký B."},{"id":41,"type":"true_false","question":"Học phần học trước bắt buộc sinh viên phải đạt học phần A trước khi học học phần B.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":false},{"key":"false","label":"S","text":"Sai","correct":true}],"answerKey":"false","answerLabel":"Sai","keyLabel":"S","answerText":"Sai","explanation":"Theo Điều 4 Khoản 1 Điểm d, học phần học trước chỉ yêu cầu đã dự thi môn A, không bắt buộc phải đạt."},{"id":42,"type":"true_false","question":"Sinh viên vắng thi có lý do chính đáng, có minh chứng hợp lệ và được chấp thuận có thể được ghi điểm I.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":true},{"key":"false","label":"S","text":"Sai","correct":false}],"answerKey":"true","answerLabel":"Đúng","keyLabel":"Đ","answerText":"Đúng","explanation":"Theo Điều 12 Khoản 4 và Điều 13 Khoản 3 Điểm c, vắng thi có lý do chính đáng được chấp thuận sẽ nhận điểm I."},{"id":43,"type":"true_false","question":"ĐTBCHK không tính điểm F.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":false},{"key":"false","label":"S","text":"Sai","correct":true}],"answerKey":"false","answerLabel":"Sai","keyLabel":"S","answerText":"Sai","explanation":"Theo Điều 15 Khoản 1 Điểm b, ĐTBCHK tính cả các học phần có điểm không đạt (điểm F)."},{"id":44,"type":"true_false","question":"ĐTBCTL được tính theo kết quả học tập tích lũy từ đầu khóa đến thời điểm xét.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":true},{"key":"false","label":"S","text":"Sai","correct":false}],"answerKey":"true","answerLabel":"Đúng","keyLabel":"Đ","answerText":"Đúng","explanation":"Theo Điều 15 Khoản 1 Điểm b, ĐTBCTL tính trên các học phần đã tích lũy từ đầu khóa đến thời điểm xét."},{"id":45,"type":"true_false","question":"Nghỉ học tạm thời vì lý do cá nhân không bị giới hạn về số học kỳ liên tiếp.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":false},{"key":"false","label":"S","text":"Sai","correct":true}],"answerKey":"false","answerLabel":"Sai","keyLabel":"S","answerText":"Sai","explanation":"Theo Điều 21 Khoản 2, nghỉ vì lý do cá nhân bị giới hạn không vượt quá 03 học kỳ liên tiếp."},{"id":46,"type":"true_false","question":"Trường hợp sinh viên đang học cùng lúc hai chương trình, nếu ĐTBCTL của chương trình thứ nhất xuống dưới mức Trung bình thì sinh viên bị buộc dừng học chương trình thứ hai.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":true},{"key":"false","label":"S","text":"Sai","correct":false}],"answerKey":"true","answerLabel":"Đúng","keyLabel":"Đ","answerText":"Đúng","explanation":"Theo Điều 24 Khoản 3, nếu ĐTBCTL chương trình thứ nhất dưới mức Trung bình (< 2.0) thì phải dừng học chương trình thứ hai ở học kỳ tiếp theo."},{"id":47,"type":"true_false","question":"Ký hiệu R dùng để chỉ trường hợp sinh viên được rút học phần hợp lệ.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":true},{"key":"false","label":"S","text":"Sai","correct":false}],"answerKey":"true","answerLabel":"Đúng","keyLabel":"Đ","answerText":"Đúng","explanation":"Theo Điều 9 Khoản 6 Điểm c và Điều 13 Khoản 3 Điểm c, điểm R dành cho các học phần được phép rút hợp lệ."},{"id":48,"type":"true_false","question":"Mọi học phần trong chương trình đào tạo đều bắt buộc phải tính vào ĐTBCTL.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":false},{"key":"false","label":"S","text":"Sai","correct":true}],"answerKey":"false","answerLabel":"Sai","keyLabel":"S","answerText":"Sai","explanation":"Theo Điều 15 Khoản 1 Điểm b và Slide 21, các học phần điều kiện (GDQP, GDTC) và các điểm chữ P, I, X, R, M không được tính vào ĐTBCTL."}],"pdfSize":"283 KB"},{"id":"nghiquyet","name":"Nghị quyết 71","title":"Nghị quyết 71-NQ/TW","eyebrow":"Bộ đề 02","description":"40 câu hỏi về Nghị quyết 71-NQ/TW của Bộ Chính trị, kèm đáp án và giải thích theo tài liệu ôn tập.","pdf":"assets/Dap_an_Nghi_quyet.pdf","source":"dataa/de_va_dap_an_nghi_quyet.json","count":40,"questions":[{"id":1,"type":"multiple_choice","question":"Nghị quyết số 71-NQ/TW xác định vai trò chủ đạo của Nhà nước trong phát triển giáo dục và đào tạo được thể hiện thông qua phương thức nào?","options":[{"key":"a","label":"A","text":"Nhà nước giữ vai trò chủ đạo, lấy đầu tư công dẫn dắt và thu hút mạnh mẽ nguồn lực xã hội để hiện đại hóa toàn diện hệ thống giáo dục.","correct":true},{"key":"b","label":"B","text":"Nhà nước bao cấp toàn bộ 100% học phí và chi phí sinh hoạt cho mọi bậc học từ mầm non đến tiến sĩ.","correct":false},{"key":"c","label":"C","text":"Nhà nước chuyển toàn bộ quyền đầu tư tài chính cho các tập đoàn kinh tế tư nhân nắm giữ.","correct":false},{"key":"d","label":"D","text":"Nhà nước chỉ quản lý hành chính, không tham gia đầu tư vào cơ sở vật chất trường học.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Nhà nước giữ vai trò chủ đạo, lấy đầu tư công dẫn dắt và thu hút mạnh mẽ nguồn lực xã hội để hiện đại hóa toàn diện hệ thống giáo dục.","explanation":"Theo Nghị quyết 71-NQ/TW và slide bài giảng (trang 56/60): Nhà nước giữ vai trò chủ đạo, lấy đầu tư công dẫn dắt và thu hút mạnh mẽ nguồn lực xã hội để hiện đại hóa toàn diện hệ thống giáo dục (tương ứng với phương án A ở đề thi)."},{"id":2,"type":"multiple_choice","question":"Về cơ cấu hệ thống giáo dục quốc dân, quan điểm của Nghị quyết 71-NQ/TW đối với giáo dục công lập và ngoài công lập là gì?","options":[{"key":"a","label":"A","text":"Giáo dục ngoài công lập giữ vị thế độc tôn, giáo dục công lập chỉ dành cho vùng sâu vùng xa.","correct":false},{"key":"b","label":"B","text":"Giáo dục công lập là trụ cột, giáo dục ngoài công lập là thành phần quan trọng.","correct":true},{"key":"c","label":"C","text":"Xóa bỏ hoàn toàn giáo dục ngoài công lập để quốc hữu hóa 100% trường học.","correct":false},{"key":"d","label":"D","text":"Giáo dục công lập và ngoài công lập hoàn toàn bình đẳng về nguồn tài trợ từ ngân sách nhà nước thường xuyên.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Giáo dục công lập là trụ cột, giáo dục ngoài công lập là thành phần quan trọng.","explanation":"Theo Nghị quyết 71-NQ/TW và slide 61, 62: Giáo dục công lập là trụ cột, giáo dục ngoài công lập là thành phần quan trọng."},{"id":3,"type":"multiple_choice","question":"Mục tiêu chỉ số giáo dục đóng góp vào Chỉ số Phát triển Con người (HDI) của Việt Nam đến năm 2030 theo Nghị quyết 71-NQ/TW là bao nhiêu?","options":[{"key":"a","label":"A","text":"Không đặt ra chỉ tiêu định lượng cụ thể về HDI mà chỉ đánh giá định tính.","correct":false},{"key":"b","label":"B","text":"Đạt mức trung bình của nhóm các nước có thu nhập thấp.","correct":false},{"key":"c","label":"C","text":"Đạt trên 0,65; chỉ số bất bình đẳng giáo dục dưới 20%.","correct":false},{"key":"d","label":"D","text":"Đạt > 0,8; chỉ số bất bình đẳng giáo dục giảm xuống < 10%.","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Đạt > 0,8; chỉ số bất bình đẳng giáo dục giảm xuống < 10%.","explanation":"Theo slide 65: Chỉ số giáo dục đóng góp vào HDI đạt > 0,8; chỉ số bất bình đẳng giáo dục giảm xuống < 10%."},{"id":4,"type":"multiple_choice","question":"Chỉ tiêu nào sau đây về nghiên cứu, đổi mới sáng tạo trong các cơ sở giáo dục đại học được xác định cụ thể trong Nghị quyết 71-NQ/TW?","options":[{"key":"a","label":"A","text":"Chỉ tập trung xuất bản sách giáo khoa trong nước, không bắt buộc công bố quốc tế.","correct":false},{"key":"b","label":"B","text":"Cắt giảm các đề tài nghiên cứu cơ bản để tập trung vào gia công công nghệ.","correct":false},{"key":"c","label":"C","text":"Tăng bình quân 12%/năm đối với công bố khoa học quốc tế và nguồn thu từ KH-CN; tăng 16%/năm đối với đăng ký sáng chế, văn bằng bảo hộ sáng chế.","correct":true},{"key":"d","label":"D","text":"Tăng bình quân 5%/năm về công bố khoa học quốc tế.","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Tăng bình quân 12%/năm đối với công bố khoa học quốc tế và nguồn thu từ KH-CN; tăng 16%/năm đối với đăng ký sáng chế, văn bằng bảo hộ sáng chế.","explanation":"Theo slide 67: Tăng bình quân 12%/năm đối với công bố khoa học quốc tế và nguồn thu từ KH-CN; tăng 16%/năm đối với đăng ký sáng chế, văn bằng bảo hộ sáng chế."},{"id":5,"type":"multiple_choice","question":"Đến năm 2030, Nghị quyết 71-NQ/TW đặt mục tiêu có bao nhiêu cơ sở giáo dục đại học của Việt Nam thuộc Top 200 châu Á?","options":[{"key":"a","label":"A","text":"Không đặt mục tiêu xếp hạng theo các tiêu chuẩn quốc tế.","correct":false},{"key":"b","label":"B","text":"Phấn đấu ít nhất 3 cơ sở.","correct":false},{"key":"c","label":"C","text":"Phấn đấu tất cả các trường đại học công lập đều vào Top 200 châu Á.","correct":false},{"key":"d","label":"D","text":"Phấn đấu ≥ 8 cơ sở giáo dục đại học thuộc Top 200 châu Á (và ≥ 1 cơ sở thuộc Top 100 thế giới trong một số lĩnh vực).","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Phấn đấu ≥ 8 cơ sở giáo dục đại học thuộc Top 200 châu Á (và ≥ 1 cơ sở thuộc Top 100 thế giới trong một số lĩnh vực).","explanation":"Theo slide 63, 64, 67: Phấn đấu ≥ 8 cơ sở giáo dục đại học thuộc Top 200 châu Á (và ≥ 1 cơ sở thuộc Top 100 thế giới trong một số lĩnh vực)."},{"id":6,"type":"multiple_choice","question":"Đâu là giải pháp mang tính đột phá về mô hình nhân sự giảng viên được Nghị quyết 71-NQ/TW khuyến khích triển khai?","options":[{"key":"a","label":"A","text":"Chuyển toàn bộ giảng viên cơ hữu sang chế độ hợp đồng thời vụ từng học kỳ.","correct":false},{"key":"b","label":"B","text":"Giảm tỷ lệ giảng viên có trình độ tiến sĩ để tiết kiệm ngân sách chi lương.","correct":false},{"key":"c","label":"C","text":"Áp dụng chế độ giảng viên đồng cơ hữu, huy động người giỏi và chuyên gia ngoài ngành tham gia giảng dạy, nghiên cứu.","correct":true},{"key":"d","label":"D","text":"Cấm tuyệt đối việc kiêm nhiệm, cán bộ ngoài ngành không được tham gia giảng dạy.","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Áp dụng chế độ giảng viên đồng cơ hữu, huy động người giỏi và chuyên gia ngoài ngành tham gia giảng dạy, nghiên cứu.","explanation":"Theo slide 73: Áp dụng chế độ giảng viên đồng cơ hữu, huy động người giỏi ngoài ngành tham gia giảng dạy và nghiên cứu."},{"id":7,"type":"multiple_choice","question":"Chương trình mục tiêu quốc gia về Giáo dục và Đào tạo được định hướng triển khai trong giai đoạn nào theo Nghị quyết 71-NQ/TW?","options":[{"key":"a","label":"A","text":"Giai đoạn 2030-2045.","correct":false},{"key":"b","label":"B","text":"Giai đoạn 2020-2025.","correct":false},{"key":"c","label":"C","text":"Giai đoạn 2025-2030.","correct":false},{"key":"d","label":"D","text":"Giai đoạn 2026-2035.","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Giai đoạn 2026-2035.","explanation":"Theo slide 74: Triển khai Chương trình mục tiêu quốc gia về GD và ĐT giai đoạn 2026-2035."},{"id":8,"type":"multiple_choice","question":"Nghị quyết 71-NQ/TW đề ra giải pháp nào để kết nối trực tiếp môi trường nghiên cứu khoa học với ứng dụng thực tế sản xuất tại các trường đại học?","options":[{"key":"a","label":"A","text":"Đưa toàn bộ các trường đại học kỹ thuật ra khỏi các thành phố lớn.","correct":false},{"key":"b","label":"B","text":"Cấm sinh viên và giảng viên tham gia các hoạt động thương mại hóa nghiên cứu.","correct":false},{"key":"c","label":"C","text":"Buộc các viện nghiên cứu phải giải thể để nhập vào các phòng ban hành chính.","correct":false},{"key":"d","label":"D","text":"Phát triển khu đô thị công nghệ cao - đại học; hỗ trợ giảng viên, sinh viên mở startup, spin-off (doanh nghiệp khởi nguồn công nghệ).","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Phát triển khu đô thị công nghệ cao - đại học; hỗ trợ giảng viên, sinh viên mở startup, spin-off (doanh nghiệp khởi nguồn công nghệ).","explanation":"Theo slide 81: Phát triển khu đô thị công nghệ cao - đại học; hỗ trợ giảng viên, sinh viên mở startup, spin-off."},{"id":9,"type":"multiple_choice","question":"Trong kiểm soát chất lượng đào tạo sau đại học và các ngành đặc thù, Nghị quyết 71-NQ/TW yêu cầu thực hiện biện pháp gì?","options":[{"key":"a","label":"A","text":"Siết chặt chất lượng đầu ra, kiểm soát chặt đào tạo tiến sĩ (đặc biệt đối với cán bộ, công chức) và các ngành đặc thù như sư phạm, sức khỏe, pháp luật.","correct":true},{"key":"b","label":"B","text":"Miễn thẩm định luận án tiến sĩ đối với cán bộ, công chức giữ chức vụ lãnh đạo.","correct":false},{"key":"c","label":"C","text":"Bãi bỏ quy định công bố khoa học quốc tế đối với nghiên cứu sinh.","correct":false},{"key":"d","label":"D","text":"Mở rộng cấp bằng tiến sĩ dựa trên số năm công tác thâm niên thay vì công trình nghiên cứu.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Siết chặt chất lượng đầu ra, kiểm soát chặt đào tạo tiến sĩ (đặc biệt đối với cán bộ, công chức) và các ngành đặc thù như sư phạm, sức khỏe, pháp luật.","explanation":"Theo slide 82: Tuyển sinh và Quản lý chất lượng: Đổi mới tuyển sinh theo năng lực, siết chặt chất lượng đầu ra; kiểm soát chặt đào tạo tiến sĩ (đặc biệt đối với cán bộ, công chức) và các ngành đặc thù (sư phạm, sức khỏe, pháp luật)."},{"id":10,"type":"multiple_choice","question":"Nghị quyết 71-NQ/TW định hướng từng bước đưa ngoại ngữ nào trở thành ngôn ngữ thứ hai trong hệ thống giáo dục Việt Nam?","options":[{"key":"a","label":"A","text":"Tiếng Nga.","correct":false},{"key":"b","label":"B","text":"Tiếng Pháp.","correct":false},{"key":"c","label":"C","text":"Tiếng Anh.","correct":true},{"key":"d","label":"D","text":"Tiếng Trung Quốc.","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Tiếng Anh.","explanation":"Theo slide 70, 79: Từng bước đưa tiếng Anh trở thành ngôn ngữ thứ hai trong hệ thống giáo dục Việt Nam."},{"id":11,"type":"multiple_choice","question":"Đến năm 2030, Nghị quyết 71-NQ/TW yêu cầu hoàn thành 100% mạng lưới cơ sở giáo dục nào đối với vùng đồng bào thiểu số?","options":[{"key":"a","label":"A","text":"Mạng lưới trường đào tạo nghề tư thục chất lượng cao.","correct":false},{"key":"b","label":"B","text":"Mạng lưới các trường đại học quốc tế vùng sâu vùng xa.","correct":false},{"key":"c","label":"C","text":"Mạng lưới trung tâm đào tạo từ xa liên kết nước ngoài.","correct":false},{"key":"d","label":"D","text":"Mạng lưới trường phổ thông dân tộc nội trú.","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Mạng lưới trường phổ thông dân tộc nội trú.","explanation":"Theo slide 78: Hoàn thành mạng lưới trường nội trú dân tộc thiểu số trước 2030."},{"id":12,"type":"multiple_choice","question":"Đâu là tỷ lệ người trong độ tuổi theo học các trình độ sau THPT được Nghị quyết 71-NQ/TW đặt ra đến năm 2030?","options":[{"key":"a","label":"A","text":"Đạt khoảng 25%.","correct":false},{"key":"b","label":"B","text":"Duy trì mức 30% như giai đoạn trước.","correct":false},{"key":"c","label":"C","text":"Đạt 80% lực lượng lao động cả nước.","correct":false},{"key":"d","label":"D","text":"Đạt 50% (trong đó 24% lực lượng lao động có trình độ cao đẳng, đại học trở lên).","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Đạt 50% (trong đó 24% lực lượng lao động có trình độ cao đẳng, đại học trở lên).","explanation":"Theo slide 66, 71: Đạt 50% người trong độ tuổi theo học sau THPT (trong đó 24% lực lượng lao động có trình độ cao đẳng, đại học trở lên)."},{"id":13,"type":"multiple_choice","question":"Vấn đề bảo đảm an ninh văn hóa trong hội nhập quốc tế về giáo dục được Nghị quyết 71-NQ/TW quán triệt như thế nào?","options":[{"key":"a","label":"A","text":"Cấm mở phân hiệu các trường đại học Việt Nam ở nước ngoài.","correct":false},{"key":"b","label":"B","text":"Bảo đảm an ninh văn hóa đối với chương trình có yếu tố nước ngoài; giữ gìn bản sắc và quảng bá văn hóa Việt Nam ra thế giới.","correct":true},{"key":"c","label":"C","text":"Tiếp nhận toàn bộ chương trình giáo dục nước ngoài mà không cần kiểm duyệt nội dung.","correct":false},{"key":"d","label":"D","text":"Ngừng hoàn toàn việc giảng dạy tiếng Việt cho người nước ngoài.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Bảo đảm an ninh văn hóa đối với chương trình có yếu tố nước ngoài; giữ gìn bản sắc và quảng bá văn hóa Việt Nam ra thế giới.","explanation":"Theo slide 83: Bảo đảm an ninh văn hóa đối với chương trình có yếu tố nước ngoài; giữ gìn bản sắc và quảng bá văn hóa Việt Nam ra nước ngoài."},{"id":14,"type":"multiple_choice","question":"Điểm mới về tổ chức và sắp xếp mạng lưới cơ sở giáo dục đại học theo Nghị quyết 71-NQ/TW là gì?","options":[{"key":"a","label":"A","text":"Tăng thêm các tầng nấc quản lý trung gian để siết chặt kỷ luật.","correct":false},{"key":"b","label":"B","text":"Xóa bỏ trung gian, sáp nhập hoặc giải thể trường không đạt chuẩn; nghiên cứu sáp nhập viện nghiên cứu vào trường đại học.","correct":true},{"key":"c","label":"C","text":"Chuyển toàn bộ các trường đại học trực thuộc các Bộ về cho tư nhân mua lại.","correct":false},{"key":"d","label":"D","text":"Mỗi huyện phải thành lập ít nhất một trường đại học đa ngành.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Xóa bỏ trung gian, sáp nhập hoặc giải thể trường không đạt chuẩn; nghiên cứu sáp nhập viện nghiên cứu vào trường đại học.","explanation":"Theo slide 81: Tái cấu trúc: Xóa bỏ trung gian, sáp nhập, giải thể trường không đạt chuẩn; nghiên cứu sáp nhập viện nghiên cứu vào trường đại học."},{"id":15,"type":"multiple_choice","question":"Theo Nghị quyết 71-NQ/TW, phấn đấu đến năm 2030 chính sách nào sau đây đối với sách giáo khoa phổ thông sẽ được thực hiện?","options":[{"key":"a","label":"A","text":"Phấn đấu thực hiện miễn phí sách giáo khoa cho học sinh phổ thông.","correct":true},{"key":"b","label":"B","text":"Bắt buộc học sinh phải mua lại sách mới mỗi năm, cấm dùng lại sách cũ.","correct":false},{"key":"c","label":"C","text":"Bãi bỏ sách giáo khoa giấy để thay bằng 100% video bài giảng tự do.","correct":false},{"key":"d","label":"D","text":"Bán đấu giá sách giáo khoa bản quyền cho nước ngoài.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Phấn đấu thực hiện miễn phí sách giáo khoa cho học sinh phổ thông.","explanation":"Theo slide 79: Cung cấp 1 bộ SGK thống nhất toàn quốc, phấn đấu miễn phí SGK đến năm 2030."},{"id":16,"type":"multiple_choice","question":"Vai trò của doanh nghiệp trong công tác đào tạo giáo dục nghề nghiệp theo Nghị quyết 71-NQ/TW được nâng tầm ra sao?","options":[{"key":"a","label":"A","text":"Bắt buộc doanh nghiệp phải đóng 50% lợi nhuận sau thuế cho quỹ nhà trường.","correct":false},{"key":"b","label":"B","text":"Doanh nghiệp chỉ đóng vai trò tuyển dụng, không được tham gia đóng góp ý kiến về chương trình đào tạo.","correct":false},{"key":"c","label":"C","text":"Khuyến khích doanh nghiệp thành lập cơ sở GDNN, lập quỹ đào tạo nhân lực và tham gia trực tiếp vào quá trình đào tạo thực hành.","correct":true},{"key":"d","label":"D","text":"Giao toàn bộ hệ thống trường công lập cho doanh nghiệp toàn quyền định đoạt nội dung giảng dạy chính trị.","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Khuyến khích doanh nghiệp thành lập cơ sở GDNN, lập quỹ đào tạo nhân lực và tham gia trực tiếp vào quá trình đào tạo thực hành.","explanation":"Theo slide 80, 84: Khuyến khích doanh nghiệp thành lập cơ sở GDNN, lập quỹ đào tạo nhân lực và tham gia trực tiếp vào quá trình đào tạo thực hành."},{"id":17,"type":"multiple_choice","question":"Mục tiêu giáo dục toàn diện của Nghị quyết 71-NQ/TW hướng tới sự kết hợp cân đối giữa các yếu tố nào?","options":[{"key":"a","label":"A","text":"Coi trọng trí lực, xem nhẹ giáo dục thể chất và mỹ thuật học đường.","correct":false},{"key":"b","label":"B","text":"Tăng cường giáo dục toàn diện đức, trí, thể, mỹ và hệ giá trị con người mới.","correct":true},{"key":"c","label":"C","text":"Đặt điểm số thi cử làm thước đo duy nhất đánh giá phẩm chất đạo đức.","correct":false},{"key":"d","label":"D","text":"Chỉ tập trung vào kỹ năng kiếm tiền và đầu tư tài chính cá nhân.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Tăng cường giáo dục toàn diện đức, trí, thể, mỹ và hệ giá trị con người mới.","explanation":"Theo slide 76, 85: Tăng cường giáo dục toàn diện đức, trí, thể, mỹ và hệ giá trị con người mới."},{"id":18,"type":"multiple_choice","question":"Tầm nhìn đến năm 2035 của giáo dục Việt Nam được xác định trong Nghị quyết 71-NQ/TW bao gồm chỉ tiêu nào sau đây?","options":[{"key":"a","label":"A","text":"Hoàn thành phổ cập THPT và tương đương; chỉ số đóng góp của giáo dục vào HDI đạt > 0,85.","correct":true},{"key":"b","label":"B","text":"Miễn hoàn toàn học phí cho tất cả bậc học sau đại học.","correct":false},{"key":"c","label":"C","text":"Đưa 100% học sinh phổ thông đi du học nước ngoài.","correct":false},{"key":"d","label":"D","text":"Giảm số lượng trường đại học xuống dưới 20 trường trên toàn quốc.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Hoàn thành phổ cập THPT và tương đương; chỉ số đóng góp của giáo dục vào HDI đạt > 0,85.","explanation":"Theo slide 63, 68, 86: Mục tiêu đến năm 2035: Hoàn thành phổ cập THPT và tương đương; chỉ số giáo dục đóng góp vào HDI đạt > 0,85."},{"id":19,"type":"multiple_choice","question":"Giải pháp đổi mới thi cử, đánh giá học sinh trong Nghị quyết 71-NQ/TW tập trung vào mục tiêu cốt lõi nào?","options":[{"key":"a","label":"A","text":"Tăng tần suất các kỳ thi xếp hạng để tạo áp lực học tập tối đa.","correct":false},{"key":"b","label":"B","text":"Bãi bỏ hoàn toàn các kỳ thi sát hạch đầu ra ở tất cả các cấp học.","correct":false},{"key":"c","label":"C","text":"Giao quyền cấp bằng tốt nghiệp trực tiếp cho các trung tâm dạy thêm.","correct":false},{"key":"d","label":"D","text":"Đánh giá trung thực, khách quan theo năng lực thực chất; khắc phục triệt để bệnh thành tích và dạy thêm - học thêm tràn lan.","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Đánh giá trung thực, khách quan theo năng lực thực chất; khắc phục triệt để bệnh thành tích và dạy thêm - học thêm tràn lan.","explanation":"Theo slide 79, 87: Đánh giá trung thực, khách quan theo năng lực thực chất; khắc phục triệt để bệnh thành tích và dạy thêm - học thêm tràn lan."},{"id":20,"type":"multiple_choice","question":"Sinh viên có thể góp phần thực hiện hiệu quả Nghị quyết 71-NQ/TW thông qua hành động thiết thực nào trong quá trình học tập?","options":[{"key":"a","label":"A","text":"Chỉ học để đối phó thi cử, thụ động ghi chép và không tham gia các hoạt động ngoại khóa.","correct":false},{"key":"b","label":"B","text":"Rèn luyện văn hóa liêm chính học thuật, chủ động tự học suốt đời, tích cực nghiên cứu khoa học và nâng cao năng lực ngoại ngữ, công nghệ số.","correct":true},{"key":"c","label":"C","text":"Mua bán tiểu luận, thuê người làm đề tài nghiên cứu khoa học để lấy điểm cao.","correct":false},{"key":"d","label":"D","text":"Thờ ơ với các phong trào đổi mới phương pháp học tập của nhà trường.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Rèn luyện văn hóa liêm chính học thuật, chủ động tự học suốt đời, tích cực nghiên cứu khoa học và nâng cao năng lực ngoại ngữ, công nghệ số.","explanation":"Theo slide 88: Rèn luyện văn hóa liêm chính học thuật, chủ động tự học suốt đời, tích cực nghiên cứu khoa học và nâng cao năng lực ngoại ngữ, công nghệ số."},{"id":21,"type":"multiple_choice","question":"Quan điểm của Đảng trong Nghị quyết 72-NQ/TW xác định \"bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân\" giữ vị trí nào?","options":[{"key":"a","label":"A","text":"Là một nhiệm vụ phụ trợ kinh tế, chỉ thực hiện khi ngân sách địa phương có thặng dư lớn.","correct":false},{"key":"b","label":"B","text":"Là lĩnh vực thuần túy thương mại tuân theo quy luật cung - cầu thị trường tự do.","correct":false},{"key":"c","label":"C","text":"Là mục tiêu, là động lực, là nhiệm vụ chính trị hàng đầu, giữ vị trí ưu tiên trong các chiến lược, chính sách phát triển.","correct":true},{"key":"d","label":"D","text":"Là trách nhiệm riêng của cá nhân mỗi gia đình, nhà nước không can thiệp chính sách.","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Là mục tiêu, là động lực, là nhiệm vụ chính trị hàng đầu, giữ vị trí ưu tiên trong các chiến lược, chính sách phát triển.","explanation":"Theo slide 25, 26: Là mục tiêu, là động lực, là nhiệm vụ chính trị hàng đầu, giữ vị trí ưu tiên trong các chiến lược, chính sách phát triển."},{"id":22,"type":"multiple_choice","question":"Chủ thể trung tâm được ưu tiên cao nhất trong xây dựng và thụ hưởng chính sách sức khỏe theo Nghị quyết 72-NQ/TW là ai?","options":[{"key":"a","label":"A","text":"Các công ty kinh doanh bảo hiểm nhân thọ thương mại.","correct":false},{"key":"b","label":"B","text":"Người dân, trong đó quan tâm đặc biệt đến trẻ em, người nghèo, các đối tượng chính sách xã hội và bảo đảm bình đẳng giới.","correct":true},{"key":"c","label":"C","text":"Các doanh nghiệp sản xuất và nhập khẩu trang thiết bị y tế.","correct":false},{"key":"d","label":"D","text":"Các bệnh viện đa khoa tư nhân quy mô lớn.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Người dân, trong đó quan tâm đặc biệt đến trẻ em, người nghèo, các đối tượng chính sách xã hội và bảo đảm bình đẳng giới.","explanation":"Theo slide 26, 27: Người dân, trong đó quan tâm đặc biệt đến trẻ em, người nghèo, các đối tượng chính sách xã hội và bảo đảm bình đẳng giới."},{"id":23,"type":"multiple_choice","question":"Mục tiêu tuổi thọ trung bình và số năm sống khỏe mạnh của người Việt Nam đến năm 2030 được Nghị quyết 72-NQ/TW xác định là:","options":[{"key":"a","label":"A","text":"Tuổi thọ trung bình đạt 75,5 tuổi, trong đó số năm sống khỏe mạnh đạt tối thiểu 68 năm.","correct":true},{"key":"b","label":"B","text":"Không đề ra chỉ tiêu số năm sống khỏe mạnh.","correct":false},{"key":"c","label":"C","text":"Tuổi thọ trung bình đạt 70 tuổi, sống khỏe mạnh đạt 60 năm.","correct":false},{"key":"d","label":"D","text":"Tuổi thọ trung bình đạt trên 85 tuổi, số năm sống khỏe mạnh đạt 80 năm.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Tuổi thọ trung bình đạt 75,5 tuổi, trong đó số năm sống khỏe mạnh đạt tối thiểu 68 năm.","explanation":"Theo slide 28, 29, 30: Tuổi thọ trung bình đạt 75,5 tuổi, trong đó số năm sống khỏe mạnh đạt tối thiểu 68 năm."},{"id":24,"type":"multiple_choice","question":"Đến năm 2030, tỷ lệ bao phủ Bảo hiểm y tế (BHYT) toàn dân theo Nghị quyết 72-NQ/TW được đặt ra là bao nhiêu?","options":[{"key":"a","label":"A","text":"Đạt 85% dân số.","correct":false},{"key":"b","label":"B","text":"Tùy thuộc vào khả năng đóng phí tự nguyện của từng địa phương.","correct":false},{"key":"c","label":"C","text":"Đạt trên 95% vào năm 2026 và đạt bao phủ BHYT toàn dân (100%) vào năm 2030.","correct":true},{"key":"d","label":"D","text":"Duy trì ở mức 90% dân số.","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Đạt trên 95% vào năm 2026 và đạt bao phủ BHYT toàn dân (100%) vào năm 2030.","explanation":"Theo slide 29, 30: Đạt trên 95% vào năm 2026 và đạt bao phủ BHYT toàn dân (100%) vào năm 2030."},{"id":25,"type":"multiple_choice","question":"Chính sách miễn viện phí cơ bản theo phạm vi quyền lợi BHYT được Nghị quyết 72-NQ/TW định hướng hoàn thành vào năm nào?","options":[{"key":"a","label":"A","text":"Không có chủ trương miễn viện phí cơ bản.","correct":false},{"key":"b","label":"B","text":"Đến năm 2026.","correct":false},{"key":"c","label":"C","text":"Đến năm 2030 (theo lộ trình từng bước, ưu tiên người nghèo, yếu thế, người thu nhập thấp).","correct":true},{"key":"d","label":"D","text":"Đến năm 2045.","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Đến năm 2030 (theo lộ trình từng bước, ưu tiên người nghèo, yếu thế, người thu nhập thấp).","explanation":"Theo slide 30, 31: Đến năm 2030 (theo lộ trình từng bước, ưu tiên người nghèo, yếu thế, người thu nhập thấp)."},{"id":26,"type":"multiple_choice","question":"Nghị quyết 72-NQ/TW đặt mục tiêu nâng tỷ lệ khám bệnh, chữa bệnh BHYT tại trạm y tế cấp xã lên mức bao nhiêu vào năm 2030?","options":[{"key":"a","label":"A","text":"Đạt trên 50%.","correct":false},{"key":"b","label":"B","text":"Đạt 100% các ca phẫu thuật chuyên khoa sâu.","correct":false},{"key":"c","label":"C","text":"Đạt trên 5%.","correct":false},{"key":"d","label":"D","text":"Đạt trên 20%.","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Đạt trên 20%.","explanation":"Theo slide 30, 32: Nâng tỷ lệ khám chữa bệnh BHYT tại xã lên trên 20% vào năm 2030."},{"id":27,"type":"multiple_choice","question":"Dự thảo các đạo luật nào sau đây được Nghị quyết 72-NQ/TW yêu cầu tập trung hoàn thiện và ban hành trong giai đoạn 2026-2030?","options":[{"key":"a","label":"A","text":"Luật Năng lượng nguyên tử, Luật Hàng không dân dụng, Luật Viễn thông.","correct":false},{"key":"b","label":"B","text":"Luật Chứng khoán và Luật Quản lý nợ công.","correct":false},{"key":"c","label":"C","text":"Luật Thương mại điện tử, Luật Sở hữu trí tuệ, Luật Du lịch.","correct":false},{"key":"d","label":"D","text":"Các Luật về Dân số, Phòng bệnh, An toàn thực phẩm, Thiết bị y tế, Y học cổ truyền.","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Các Luật về Dân số, Phòng bệnh, An toàn thực phẩm, Thiết bị y tế, Y học cổ truyền.","explanation":"Theo slide 33, 37: Các Luật về Dân số, Phòng bệnh, An toàn thực phẩm, Thiết bị y tế, Y học cổ truyền."},{"id":28,"type":"multiple_choice","question":"Nghị quyết 72-NQ/TW quy định mỗi tỉnh, thành phố trực thuộc Trung ương phải bảo đảm cơ sở y tế chuyên sâu nào?","options":[{"key":"a","label":"A","text":"Mỗi tỉnh chỉ duy trì 1 trạm xá duy nhất kết hợp quân - dân y.","correct":false},{"key":"b","label":"B","text":"Có ít nhất 5 bệnh viện cấp trung ương trực thuộc Bộ Y tế.","correct":false},{"key":"c","label":"C","text":"Toàn bộ các bệnh viện tỉnh đều phải chuyển thành trung tâm thẩm mỹ tư nhân.","correct":false},{"key":"d","label":"D","text":"Có ít nhất 1 bệnh viện đạt cấp chuyên sâu; có bệnh viện lão khoa hoặc bệnh viện đa khoa có chuyên khoa lão khoa.","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Có ít nhất 1 bệnh viện đạt cấp chuyên sâu; có bệnh viện lão khoa hoặc bệnh viện đa khoa có chuyên khoa lão khoa.","explanation":"Theo slide 34, 37: Có ít nhất 1 bệnh viện đạt cấp chuyên sâu; có bệnh viện lão khoa hoặc bệnh viện đa khoa có chuyên khoa lão khoa."},{"id":29,"type":"multiple_choice","question":"Về phát triển nguồn nhân lực y tế chất lượng cao, chính sách đào tạo chuyên sâu đặc thù sau đại học trong khối ngành sức khỏe do cơ quan nào quản lý?","options":[{"key":"a","label":"A","text":"Do UBND cấp xã tự thẩm định và bổ nhiệm chuyên môn.","correct":false},{"key":"b","label":"B","text":"Thực hiện đào tạo chuyên sâu đặc thù trình độ sau đại học thuộc hệ thống giáo dục quốc dân do Bộ Y tế quản lý.","correct":true},{"key":"c","label":"C","text":"Do Bộ Lao động - Thương binh và Xã hội cấp chứng chỉ nghề ngắn hạn.","correct":false},{"key":"d","label":"D","text":"Do các tổ chức phi chính phủ nước ngoài toàn quyền cấp chứng chỉ hành nghề.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Thực hiện đào tạo chuyên sâu đặc thù trình độ sau đại học thuộc hệ thống giáo dục quốc dân do Bộ Y tế quản lý.","explanation":"Theo quan điểm chỉ đạo và nội dung Nghị quyết 72-NQ/TW: Thực hiện đào tạo chuyên sâu đặc thù trình độ sau đại học thuộc hệ thống giáo dục quốc dân do Bộ Y tế quản lý."},{"id":30,"type":"multiple_choice","question":"Để chuẩn bị nguồn lực tài chính cho mở rộng gói dịch vụ và khám sàng lọc sớm, Nghị quyết 72-NQ/TW định hướng điều chỉnh mức đóng BHYT từ năm nào?","options":[{"key":"a","label":"A","text":"Tăng mức đóng gấp 5 lần ngay từ đầu năm 2026 đối với hộ cận nghèo.","correct":false},{"key":"b","label":"B","text":"Điều chỉnh mức đóng BHYT từ năm 2027 phù hợp lộ trình gắn với tăng tỷ lệ thanh toán phòng bệnh.","correct":true},{"key":"c","label":"C","text":"Giữ nguyên cố định không bao giờ thay đổi mức đóng BHYT.","correct":false},{"key":"d","label":"D","text":"Bãi bỏ nguồn đóng góp của người lao động để chi hoàn toàn từ tiền phạt vi phạm giao thông.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Điều chỉnh mức đóng BHYT từ năm 2027 phù hợp lộ trình gắn với tăng tỷ lệ thanh toán phòng bệnh.","explanation":"Theo slide 39: Điều chỉnh mức đóng BHYT từ năm 2027 phù hợp lộ trình."},{"id":31,"type":"multiple_choice","question":"Ba trụ cột số hóa y tế bắt buộc phải hoàn thành kết nối liên thông toàn diện theo Nghị quyết 72-NQ/TW là gì?","options":[{"key":"a","label":"A","text":"Sổ sức khỏe điện tử, bệnh án điện tử, đơn thuốc điện tử.","correct":true},{"key":"b","label":"B","text":"Sổ hộ khẩu điện tử, căn cước công dân và bằng lái xe số.","correct":false},{"key":"c","label":"C","text":"Hóa đơn điện tử, thẻ xe buýt điện tử và hộ chiếu vắc-xin tạm thời.","correct":false},{"key":"d","label":"D","text":"Tin nhắn SMS phòng dịch, danh bạ điện thoại và định vị GPS người bệnh.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Sổ sức khỏe điện tử, bệnh án điện tử, đơn thuốc điện tử.","explanation":"Theo slide 40: Liên thông toàn diện sổ sức khỏe điện tử, bệnh án điện tử, đơn thuốc điện tử."},{"id":32,"type":"multiple_choice","question":"Đâu là định hướng ứng dụng công nghệ mũi nhọn trong y học được Nghị quyết 72-NQ/TW ưu tiên đầu tư nghiên cứu?","options":[{"key":"a","label":"A","text":"Chỉ sử dụng các bài thuốc truyền miệng không kiểm nghiệm lâm sàng.","correct":false},{"key":"b","label":"B","text":"Cấm ứng dụng công nghệ trí tuệ nhân tạo trong xử lý hình ảnh chụp X-quang và MRI.","correct":false},{"key":"c","label":"C","text":"Ứng dụng AI, Big Data, Blockchain, IoT; phát triển công nghệ gen, nano sinh học, y học tái tạo, y học hạt nhân.","correct":true},{"key":"d","label":"D","text":"Nhập khẩu toàn bộ phần mềm chẩn đoán của nước ngoài, không phát triển ứng dụng nội địa.","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Ứng dụng AI, Big Data, Blockchain, IoT; phát triển công nghệ gen, nano sinh học, y học tái tạo, y học hạt nhân.","explanation":"Theo slide 40: Ứng dụng AI, Big Data, Blockchain, IoT trong quản trị và điều trị; phát triển các trung tâm y học hạt nhân, công nghệ gen, y học tái tạo."},{"id":33,"type":"multiple_choice","question":"Nghị quyết 72-NQ/TW đề ra giải pháp đột phá nào để tận dụng cơ sở vật chất dôi dư sau tinh gọn tổ chức hành chính cho y tế?","options":[{"key":"a","label":"A","text":"Ưu tiên dành trụ sở cơ quan nhà nước dôi dư sau sắp xếp cho các cơ sở y tế thuê, sử dụng.","correct":true},{"key":"b","label":"B","text":"Bỏ hoang các tòa nhà công vụ không sử dụng.","correct":false},{"key":"c","label":"C","text":"Phá dỡ toàn bộ các công trình cũ để bán phế liệu thu hồi vốn.","correct":false},{"key":"d","label":"D","text":"Chuyển đổi công năng toàn bộ trụ sở dôi dư thành vũ trường hoặc quán bar giải trí.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Ưu tiên dành trụ sở cơ quan nhà nước dôi dư sau sắp xếp cho các cơ sở y tế thuê, sử dụng.","explanation":"Theo slide 41: Tận dụng trụ sở dôi dư sau sắp xếp cho cơ sở y tế thuê, sử dụng."},{"id":34,"type":"multiple_choice","question":"Tầm nhìn đến năm 2045 của ngành y tế và sức khỏe nhân dân Việt Nam theo Nghị quyết 72-NQ/TW là gì?","options":[{"key":"a","label":"A","text":"Tuổi thọ trung bình đạt trên 80 tuổi (sống khỏe mạnh trên 71 năm); hệ thống y tế hiện đại, lấy phòng bệnh làm nòng cốt, ngang tầm các nước phát triển.","correct":true},{"key":"b","label":"B","text":"Duy trì tuổi thọ trung bình ở mức 72 tuổi như các nước chậm phát triển.","correct":false},{"key":"c","label":"C","text":"Đóng cửa toàn bộ các trạm y tế cấp xã để dồn về 5 bệnh viện trung ương.","correct":false},{"key":"d","label":"D","text":"Trở thành quốc gia nhập khẩu thuốc tân dược nhiều nhất khu vực châu Á.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Tuổi thọ trung bình đạt trên 80 tuổi (sống khỏe mạnh trên 71 năm); hệ thống y tế hiện đại, lấy phòng bệnh làm nòng cốt, ngang tầm các nước phát triển.","explanation":"Theo slide 35: Tuổi thọ trung bình trên 80 tuổi (sống khỏe mạnh trên 71 năm); Hệ thống y tế hiện đại, công bằng, bền vững, lấy phòng bệnh làm nòng cốt; chỉ số y tế ngang tầm các nước phát triển."},{"id":35,"type":"multiple_choice","question":"Quan điểm \"nghề y là nghề đặc biệt\" đòi hỏi phương thức quản lý và đối đãi nào theo Nghị quyết 72-NQ/TW?","options":[{"key":"a","label":"A","text":"Không yêu cầu khắt khe về chuẩn mực y đức và năng lực chuyên môn.","correct":false},{"key":"b","label":"B","text":"Áp dụng cơ chế tuyển dụng thông thường và cắt giảm các khoản phụ cấp độc hại.","correct":false},{"key":"c","label":"C","text":"Chuyển toàn bộ bác sĩ sang cơ chế ký hợp đồng khoán việc ngắn hạn theo sản phẩm.","correct":false},{"key":"d","label":"D","text":"Phải được tuyển chọn, đào tạo, sử dụng và có chính sách đãi ngộ đặc biệt trong suốt quá trình công tác.","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Phải được tuyển chọn, đào tạo, sử dụng và có chính sách đãi ngộ đặc biệt trong suốt quá trình công tác.","explanation":"Theo slide 26, 43: Phải được tuyển chọn, đào tạo, sử dụng và có chính sách đãi ngộ đặc biệt trong suốt quá trình công tác."},{"id":36,"type":"multiple_choice","question":"Nghị quyết 72-NQ/TW yêu cầu triển khai các biện pháp gì để xử lý hiện tượng tiêu cực, thương mại hóa lệch lạc trong khám chữa bệnh?","options":[{"key":"a","label":"A","text":"Cho phép quảng cáo sai sự thật về công dụng của thực phẩm chức năng trên mạng.","correct":false},{"key":"b","label":"B","text":"Tăng cường phòng chống lạm dụng, trục lợi chính sách BHYT, vi phạm pháp luật y tế và xử lý nghiêm các hành vi tiêu cực, xâm hại nhân viên y tế.","correct":true},{"key":"c","label":"C","text":"Bãi bỏ việc thanh tra, kiểm toán định kỳ các cơ sở y tế công lập và tư nhân.","correct":false},{"key":"d","label":"D","text":"Dung dưỡng cho các hành vi kê đơn thuốc vượt mức để tăng doanh thu cho trạm y tế.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Tăng cường phòng chống lạm dụng, trục lợi chính sách BHYT, vi phạm pháp luật y tế và xử lý nghiêm các hành vi tiêu cực, xâm hại nhân viên y tế.","explanation":"Theo slide 36, 44: Tăng cường phòng chống lạm dụng, trục lợi chính sách BHYT, vi phạm pháp luật y tế và xử lý nghiêm các hành vi tiêu cực, xâm hại nhân viên y tế."},{"id":37,"type":"multiple_choice","question":"Vấn đề chăm sóc sức khỏe tâm thần trong môi trường làm việc và học tập được Nghị quyết 72-NQ/TW nhấn mạnh như thế nào?","options":[{"key":"a","label":"A","text":"Không đưa nội dung tâm lý học đường vào bất kỳ chương trình giáo dục nào.","correct":false},{"key":"b","label":"B","text":"Coi nhẹ sức khỏe tâm thần, chỉ tập trung điều trị các tổn thương cơ học bên ngoài.","correct":false},{"key":"c","label":"C","text":"Chú trọng chăm sóc sức khỏe tâm thần, tạo môi trường sống, làm việc, học tập cân bằng, giảm căng thẳng, áp lực.","correct":true},{"key":"d","label":"D","text":"Bắt buộc học sinh, sinh viên tự chi trả toàn bộ viện phí điều trị tâm lý tại bệnh viện tư.","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Chú trọng chăm sóc sức khỏe tâm thần, tạo môi trường sống, làm việc, học tập cân bằng, giảm căng thẳng, áp lực.","explanation":"Theo slide 36, 45: Chú trọng chăm sóc sức khỏe tâm thần, tạo môi trường sống, làm việc, học tập cân bằng, giảm căng thẳng, áp lực."},{"id":38,"type":"multiple_choice","question":"Nhằm chủ động ứng phó với các tình huống dịch bệnh khẩn cấp, giải pháp về nguồn cung vật tư y tế trong Nghị quyết 72-NQ/TW là gì?","options":[{"key":"a","label":"A","text":"Chỉ mua thuốc khi dịch bệnh đã bùng phát trên diện rộng toàn quốc.","correct":false},{"key":"b","label":"B","text":"Chuẩn bị tốt cơ số thuốc dự trữ, thiết bị y tế, bảo đảm an ninh y tế và tự chủ về vắc-xin, thuốc thiết yếu.","correct":true},{"key":"c","label":"C","text":"Tiêu hủy toàn bộ lượng vắc-xin dự trữ khi hết năm tài chính.","correct":false},{"key":"d","label":"D","text":"Hoàn toàn trông chờ vào nguồn hàng viện trợ khẩn cấp của các tổ chức quốc tế.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Chuẩn bị tốt cơ số thuốc dự trữ, thiết bị y tế, bảo đảm an ninh y tế và tự chủ về vắc-xin, thuốc thiết yếu.","explanation":"Theo slide 39, 46: Chuẩn bị tốt cơ số thuốc dự trữ, thiết bị y tế, bảo đảm an ninh y tế và tự chủ về vắc-xin, thuốc thiết yếu."},{"id":39,"type":"multiple_choice","question":"Sinh viên ngành Công nghệ thực phẩm và Nông học có thể đóng góp thiết thực nhất vào mục tiêu dinh dưỡng học đường của Nghị quyết 72-NQ/TW bằng cách nào?","options":[{"key":"a","label":"A","text":"Khuyến khích sử dụng nước ngọt có ga thay thế cho nước lọc trong căng tin trường học.","correct":false},{"key":"b","label":"B","text":"Nghiên cứu, thiết kế và phát triển các sản phẩm thực phẩm sạch, cân đối thành phần vi chất dinh dưỡng, đảm bảo tiêu chuẩn an toàn thực phẩm cho bữa ăn học đường.","correct":true},{"key":"c","label":"C","text":"Tham gia buôn bán các thực phẩm chế biến sẵn nhiều phẩm màu và hóa chất bảo quản độc hại.","correct":false},{"key":"d","label":"D","text":"Tẩy chay việc kiểm định tồn dư hóa chất bảo vệ thực vật trong rau củ quả.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Nghiên cứu, thiết kế và phát triển các sản phẩm thực phẩm sạch, cân đối thành phần vi chất dinh dưỡng, đảm bảo tiêu chuẩn an toàn thực phẩm cho bữa ăn học đường.","explanation":"Theo slide 47: Nghiên cứu, thiết kế và phát triển các sản phẩm thực phẩm sạch, cân đối thành phần vi chất dinh dưỡng, đảm bảo tiêu chuẩn an toàn thực phẩm cho bữa ăn học đường."},{"id":40,"type":"multiple_choice","question":"Trước các thông tin lan truyền thiếu kiểm chứng về mẹo chữa bệnh và thuốc đặc trị giả trên không gian mạng, thái độ đúng đắn của sinh viên là gì?","options":[{"key":"a","label":"A","text":"Nâng cao kiến thức sức khỏe kỹ thuật số, chủ động phản biện, không lan truyền và báo cáo cơ quan chức năng các thông tin y tế sai lệch, nguy hại.","correct":true},{"key":"b","label":"B","text":"Chia sẻ ngay lên các trang mạng cá nhân để câu tương tác mà không cần xác minh.","correct":false},{"key":"c","label":"C","text":"Mua hộ người thân các loại thuốc trôi nổi được quảng cáo là \"thần dược gia truyền\" trên mạng.","correct":false},{"key":"d","label":"D","text":"Tự ý làm theo các bài thuốc dân gian truyền miệng nguy hiểm mà không tham vấn bác sĩ.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Nâng cao kiến thức sức khỏe kỹ thuật số, chủ động phản biện, không lan truyền và báo cáo cơ quan chức năng các thông tin y tế sai lệch, nguy hại.","explanation":"Thái độ đúng đắn, khoa học của sinh viên là nâng cao kiến thức sức khỏe số, phản biện thông tin sai lệch và báo cáo cơ quan chức năng."}],"pdfSize":"321 KB"},{"id":"kiemtra","name":"Đề kiểm tra","title":"Bộ đề kiểm tra tổng hợp","eyebrow":"Bộ đề 03","description":"40 câu hỏi tổng hợp từ Quy chế đào tạo và Nghị quyết 71, 72-NQ/TW của Bộ Chính trị.","pdf":"assets/Dap_an_De_kiem_tra.pdf","source":"dataa/bo_de_kiem_tra_dap_an_chuan.json","count":40,"questions":[{"id":1,"type":"true_false","question":"Mọi học phần trong chương trình đào tạo đều bắt buộc phải tính vào ĐTBCTL.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":false},{"key":"false","label":"S","text":"Sai","correct":true}],"answerKey":"false","answerLabel":"Sai","keyLabel":"S","answerText":"Sai","explanation":"Các học phần điều kiện (GDTC, GDQP-AN, Tin học, Ngoại ngữ cơ bản...) và các điểm đặc biệt (P, I, X, R, M) không được tính vào ĐTBCTL."},{"id":2,"type":"multiple_choice","question":"Học phần tự chọn được hiểu như thế nào?","options":[{"key":"a","label":"A","text":"Không được tính trong chương trình đào tạo","correct":false},{"key":"b","label":"B","text":"Sinh viên chọn theo hướng dẫn của chương trình đào tạo","correct":true},{"key":"c","label":"C","text":"Chỉ dành cho sinh viên năm cuối","correct":false},{"key":"d","label":"D","text":"Bắt buộc phải học đúng một môn xác định","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Sinh viên chọn theo hướng dẫn của chương trình đào tạo","explanation":"Theo Điều 4 Quy chế: Học phần tự chọn là học phần sinh viên được tự chọn theo hướng dẫn của Khoa nhằm đa dạng hóa hướng chuyên môn hoặc tích lũy đủ số tín chỉ."},{"id":3,"type":"true_false","question":"Ký hiệu R dùng để chỉ trường hợp sinh viên được rút học phần hợp lệ.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":true},{"key":"false","label":"S","text":"Sai","correct":false}],"answerKey":"true","answerLabel":"Đúng","keyLabel":"Đ","answerText":"Đúng","explanation":"Điểm R dùng cho các học phần sinh viên được phép rút theo quy định."},{"id":4,"type":"multiple_choice","question":"Trường hợp nào có thể làm sinh viên bị hạ một bậc xếp loại bằng?","options":[{"key":"a","label":"A","text":"Có học phần F chiếm hơn 5% tổng số tín chỉ quy định hoặc từng bị kỷ luật mức cảnh cáo","correct":true},{"key":"b","label":"B","text":"Đăng ký dưới 10 tín chỉ trong 3 học kỳ","correct":false},{"key":"c","label":"C","text":"Tổng số tín chỉ các môn đã rút nhiều hơn 5% tổng số tín chỉ","correct":false},{"key":"d","label":"D","text":"Từng rớt môn học cốt lõi","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Có học phần F chiếm hơn 5% tổng số tín chỉ quy định hoặc từng bị kỷ luật mức cảnh cáo","explanation":"Hạng tốt nghiệp Xuất sắc và Giỏi bị giảm một mức nếu khối lượng học lại (bắt buộc) > 5% tổng số tín chỉ hoặc từng bị kỷ luật từ mức cảnh cáo trở lên."},{"id":5,"type":"multiple_choice","question":"Điểm 5,5-6,4 theo thang điểm 10 tương ứng với điểm chữ nào?","options":[{"key":"a","label":"A","text":"C","correct":true},{"key":"b","label":"B","text":"D","correct":false},{"key":"c","label":"C","text":"D+","correct":false},{"key":"d","label":"D","text":"F","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"C","explanation":"Thang điểm 10 từ 5,5 - 6,4 quy đổi thành điểm chữ C (thang 4 là 2.0)."},{"id":6,"type":"true_false","question":"Sinh viên vắng thi có lý do chính đáng, có minh chứng hợp lệ và được chấp thuận có thể được ghi điểm I.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":true},{"key":"false","label":"S","text":"Sai","correct":false}],"answerKey":"true","answerLabel":"Đúng","keyLabel":"Đ","answerText":"Đúng","explanation":"Sinh viên có lý do bất khả kháng, có minh chứng hợp lệ được chấp thuận sẽ hoãn thi và hưởng điểm I (Chưa hoàn thiện)."},{"id":7,"type":"true_false","question":"Trường hợp sinh viên đang học cùng lúc hai chương trình, nếu ĐTBCTL của chương trình thứ nhất xuống dưới mức Trung bình thì sinh viên bị buộc dừng học chương trình thứ hai.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":true},{"key":"false","label":"S","text":"Sai","correct":false}],"answerKey":"true","answerLabel":"Đúng","keyLabel":"Đ","answerText":"Đúng","explanation":"Khoản 3 Điều 24 Quy chế quy định nếu ĐTB tích lũy CT1 rớt xuống dưới mức Trung bình (< 2.0) thì buộc dừng học CT2."},{"id":8,"type":"multiple_choice","question":"Sinh viên vắng quá quy định về tham dự học phần sẽ bị xử lý như thế nào?","options":[{"key":"a","label":"A","text":"Được tự động nhận điểm I","correct":false},{"key":"b","label":"B","text":"Nhận điểm R","correct":false},{"key":"c","label":"C","text":"Bị trừ điểm rèn luyện","correct":false},{"key":"d","label":"D","text":"Bị cấm thi","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Bị cấm thi","explanation":"Vắng quá số tiết quy định (> 20% lý thuyết hoặc > 0% thực hành) sẽ bị cấm thi và nhận điểm F."},{"id":9,"type":"multiple_choice","question":"Nếu học phần A là học phần tiên quyết của học phần B, trước khi đăng ký học phần B, sinh viên phải đáp ứng điều kiện nào đối với học phần A?","options":[{"key":"a","label":"A","text":"Đã đăng ký thành công và thanh toán học phí cho A","correct":false},{"key":"b","label":"B","text":"Đã học A nhưng không cần đạt","correct":false},{"key":"c","label":"C","text":"Đã học và đạt A","correct":true},{"key":"d","label":"D","text":"Đã đăng ký thành công học phần A","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Đã học và đạt A","explanation":"Học phần tiên quyết bắt buộc phải học và đạt trước khi đăng ký học phần sau."},{"id":10,"type":"multiple_choice","question":"Thời gian đào tạo tối đa của chương trình đại học chính quy đối với khóa tuyển sinh năm 2025 về trước (trừ ngành bác sĩ thú y và các chương trình tiên tiến) là bao nhiêu năm?","options":[{"key":"a","label":"A","text":"8,0 năm","correct":true},{"key":"b","label":"B","text":"7,0 năm","correct":false},{"key":"c","label":"C","text":"6,0 năm","correct":false},{"key":"d","label":"D","text":"5,0 năm","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"8,0 năm","explanation":"Khoản 7 Điều 2 Quy chế quy định thời gian tối đa đối với khóa 2025 trở về trước là 8,0 năm."},{"id":11,"type":"multiple_choice","question":"Ký hiệu R trong kết quả học tập được hiểu là gì?","options":[{"key":"a","label":"A","text":"Chưa hoàn thiện","correct":false},{"key":"b","label":"B","text":"Đạt không phân mức","correct":false},{"key":"c","label":"C","text":"Được miễn học","correct":false},{"key":"d","label":"D","text":"Rút học phần hợp lệ","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Rút học phần hợp lệ","explanation":"R là điểm dành cho học phần sinh viên được rút hợp lệ."},{"id":12,"type":"multiple_choice","question":"Nếu muốn chuyển ngành, ngoài những điều kiện khác, điểm trúng tuyển của sinh viên phải đáp ứng yêu cầu nào?","options":[{"key":"a","label":"A","text":"Cao hơn điểm chuẩn của ngành chuyển đến tối thiểu 2 điểm","correct":false},{"key":"b","label":"B","text":"Không thấp hơn điểm chuẩn của ngành muốn chuyển đến","correct":true},{"key":"c","label":"C","text":"Cao hơn 15 điểm","correct":false},{"key":"d","label":"D","text":"Đạt điểm đảm bảo chất lượng đầu vào (điểm sàn) ngành chuyển đến","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Không thấp hơn điểm chuẩn của ngành muốn chuyển đến","explanation":"Khoản 1 Điều 22: Sinh viên phải đạt điều kiện trúng tuyển của chương trình, ngành đào tạo nơi chuyển đến trong cùng khóa."},{"id":13,"type":"multiple_choice","question":"A là học phần học trước của B, điều kiện để đăng ký B là gì?","options":[{"key":"a","label":"A","text":"Đã đăng ký học và dự thi A, không bắt buộc đạt","correct":true},{"key":"b","label":"B","text":"Đã hoàn thành học phần B","correct":false},{"key":"c","label":"C","text":"Phải đạt điểm tối thiểu 5,5 ở học phần A","correct":false},{"key":"d","label":"D","text":"Đã học và phải đạt A","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Đã đăng ký học và dự thi A, không bắt buộc đạt","explanation":"Học phần học trước chỉ yêu cầu đã học và dự thi kết thúc học phần A, không bắt buộc đạt."},{"id":14,"type":"multiple_choice","question":"Điểm 6,5-6,9 theo thang điểm 10 tương ứng với điểm chữ nào?","options":[{"key":"a","label":"A","text":"B","correct":false},{"key":"b","label":"B","text":"C","correct":false},{"key":"c","label":"C","text":"B+","correct":false},{"key":"d","label":"D","text":"C+","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"C+","explanation":"6,5 - 6,9 quy đổi thành điểm chữ C+ (2.5 ở hệ 4)."},{"id":15,"type":"true_false","question":"Học phần tiên quyết yêu cầu sinh viên phải học và đạt học phần A trước khi đăng ký học phần B.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":true},{"key":"false","label":"S","text":"Sai","correct":false}],"answerKey":"true","answerLabel":"Đúng","keyLabel":"Đ","answerText":"Đúng","explanation":"Đúng với định nghĩa học phần tiên quyết."},{"id":16,"type":"true_false","question":"ĐTBCTL được tính theo kết quả học tập tích lũy từ đầu khóa đến thời điểm xét.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":true},{"key":"false","label":"S","text":"Sai","correct":false}],"answerKey":"true","answerLabel":"Đúng","keyLabel":"Đ","answerText":"Đúng","explanation":"ĐTBCTL là trung bình có trọng số của các học phần đã tích lũy tính từ đầu khóa học."},{"id":17,"type":"true_false","question":"ĐTBCHK không tính điểm F.","options":[{"key":"true","label":"Đ","text":"Đúng","correct":false},{"key":"false","label":"S","text":"Sai","correct":true}],"answerKey":"false","answerLabel":"Sai","keyLabel":"S","answerText":"Sai","explanation":"ĐTBCHK tính tất cả học phần trong học kỳ, kể cả các học phần có điểm không đạt (điểm F)."},{"id":18,"type":"multiple_choice","question":"Điểm trung bình chung tích lũy được sử dụng chủ yếu để làm gì?","options":[{"key":"a","label":"A","text":"Tính điểm rèn luyện","correct":false},{"key":"b","label":"B","text":"Xét tốt nghiệp và xếp loại bằng","correct":true},{"key":"c","label":"C","text":"Xét học bổng","correct":false},{"key":"d","label":"D","text":"Xét điều kiện làm luận văn tốt nghiệp","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Xét tốt nghiệp và xếp loại bằng","explanation":"ĐTBCTL là cơ sở xếp loại học lực toàn khóa, xét và xếp loại tốt nghiệp."},{"id":19,"type":"multiple_choice","question":"Để được dự thi kết thúc học phần lý thuyết, sinh viên phải tham dự tối thiểu bao nhiêu phần trăm số giờ?","options":[{"key":"a","label":"A","text":"70%","correct":false},{"key":"b","label":"B","text":"80%","correct":true},{"key":"c","label":"C","text":"50%","correct":false},{"key":"d","label":"D","text":"100%","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"80%","explanation":"Khoản 4 Điều 10: Tham dự tối thiểu 80% số giờ đối với các học phần lý thuyết."},{"id":20,"type":"multiple_choice","question":"Điểm trung bình chung học kỳ được tính theo nguyên tắc nào?","options":[{"key":"a","label":"A","text":"Tổng (tín chỉ × điểm quy đổi hệ 4) chia tổng số tín chỉ tương ứng","correct":true},{"key":"b","label":"B","text":"Tổng điểm hệ 10 chia số tín chỉ","correct":false},{"key":"c","label":"C","text":"Tổng điểm hệ 4 chia số tín chỉ","correct":false},{"key":"d","label":"D","text":"Điểm học tập + điểm rèn luyện quy đổi","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Tổng (tín chỉ × điểm quy đổi hệ 4) chia tổng số tín chỉ tương ứng","explanation":"ĐTBCHK được tính bằng tổng tích số giữa điểm quy đổi hệ 4 và số tín chỉ, chia cho tổng số tín chỉ."},{"id":21,"type":"multiple_choice","question":"Trong kiểm soát chất lượng đào tạo sau đại học và các ngành đặc thù, Nghị quyết 71-NQ/TW yêu cầu thực hiện biện pháp gì?","options":[{"key":"a","label":"A","text":"Bãi bỏ quy định công bố khoa học quốc tế đối với nghiên cứu sinh.","correct":false},{"key":"b","label":"B","text":"Miễn thẩm định luận án tiến sĩ đối với cán bộ, công chức giữ chức vụ lãnh đạo.","correct":false},{"key":"c","label":"C","text":"Siết chặt chất lượng đầu ra, kiểm soát chặt đào tạo tiến sĩ (đặc biệt đối với cán bộ, công chức) và các ngành đặc thù như sư phạm, sức khỏe, pháp luật.","correct":true},{"key":"d","label":"D","text":"Mở rộng cấp bằng tiến sĩ dựa trên số năm công tác thâm niên thay vì công trình nghiên cứu.","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Siết chặt chất lượng đầu ra, kiểm soát chặt đào tạo tiến sĩ (đặc biệt đối với cán bộ, công chức) và các ngành đặc thù như sư phạm, sức khỏe, pháp luật.","explanation":"Nghị quyết 71-NQ/TW quán triệt siết chặt chất lượng đầu ra, quản lý nghiêm việc đào tạo tiến sĩ và các ngành đặc thù."},{"id":22,"type":"multiple_choice","question":"Đâu là tỷ lệ người trong độ tuổi theo học các trình độ sau THPT được Nghị quyết 71-NQ/TW đặt ra đến năm 2030?","options":[{"key":"a","label":"A","text":"Đạt 50% (trong đó 24% lực lượng lao động có trình độ cao đẳng, đại học trở lên).","correct":true},{"key":"b","label":"B","text":"Duy trì mức 30% như giai đoạn trước.","correct":false},{"key":"c","label":"C","text":"Đạt khoảng 25%.","correct":false},{"key":"d","label":"D","text":"Đạt 80% lực lượng lao động cả nước.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Đạt 50% (trong đó 24% lực lượng lao động có trình độ cao đẳng, đại học trở lên).","explanation":"Mục tiêu đến 2030: 50% người trong độ tuổi theo học sau THPT (24% lao động có trình độ CĐ, ĐH trở lên)."},{"id":23,"type":"multiple_choice","question":"Mục tiêu tuổi thọ trung bình và số năm sống khỏe mạnh của người Việt Nam đến năm 2030 được Nghị quyết 72-NQ/TW xác định là:","options":[{"key":"a","label":"A","text":"Tuổi thọ trung bình đạt trên 85 tuổi, số năm sống khỏe mạnh đạt 80 năm.","correct":false},{"key":"b","label":"B","text":"Tuổi thọ trung bình đạt 75,5 tuổi, trong đó số năm sống khỏe mạnh đạt tối thiểu 68 năm.","correct":true},{"key":"c","label":"C","text":"Tuổi thọ trung bình đạt 70 tuổi, sống khỏe mạnh đạt 60 năm.","correct":false},{"key":"d","label":"D","text":"Không đề ra chỉ tiêu số năm sống khỏe mạnh.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Tuổi thọ trung bình đạt 75,5 tuổi, trong đó số năm sống khỏe mạnh đạt tối thiểu 68 năm.","explanation":"Chỉ tiêu NQ 72-NQ/TW đến 2030: Tuổi thọ TB đạt 75,5 tuổi, sống khỏe mạnh tối thiểu 68 năm."},{"id":24,"type":"multiple_choice","question":"Trước các thông tin lan truyền thiếu kiểm chứng về mẹo chữa bệnh và thuốc đặc trị giả trên không gian mạng, thái độ đúng đắn của sinh viên là gì?","options":[{"key":"a","label":"A","text":"Chia sẻ ngay lên các trang mạng cá nhân để câu tương tác mà không cần xác minh.","correct":false},{"key":"b","label":"B","text":"Nâng cao kiến thức sức khỏe kỹ thuật số, chủ động phản biện, không lan truyền và báo cáo cơ quan chức năng các thông tin y tế sai lệch, nguy hại.","correct":true},{"key":"c","label":"C","text":"Mua hộ người thân các loại thuốc trôi nổi được quảng cáo là \"thần dược gia truyền\" trên mạng.","correct":false},{"key":"d","label":"D","text":"Tự ý làm theo các bài thuốc dân gian truyền miệng nguy hiểm mà không tham vấn bác sĩ.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Nâng cao kiến thức sức khỏe kỹ thuật số, chủ động phản biện, không lan truyền và báo cáo cơ quan chức năng các thông tin y tế sai lệch, nguy hại.","explanation":"Hành động trách nhiệm của công dân và sinh viên là nâng cao kiến thức số, chủ động phản biện và ngăn chặn thông tin y tế giả."},{"id":25,"type":"multiple_choice","question":"Để chuẩn bị nguồn lực tài chính cho mở rộng gói dịch vụ và khám sàng lọc sớm, Nghị quyết 72-NQ/TW định hướng điều chỉnh mức đóng BHYT từ năm nào?","options":[{"key":"a","label":"A","text":"Giữ nguyên cố định không bao giờ thay đổi mức đóng BHYT.","correct":false},{"key":"b","label":"B","text":"Điều chỉnh mức đóng BHYT từ năm 2027 phù hợp lộ trình gắn với tăng tỷ lệ thanh toán phòng bệnh.","correct":true},{"key":"c","label":"C","text":"Tăng mức đóng gấp 5 lần ngay từ đầu năm 2026 đối với hộ cận nghèo.","correct":false},{"key":"d","label":"D","text":"Bãi bỏ nguồn đóng góp của người lao động để chi hoàn toàn từ tiền phạt vi phạm giao thông.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Điều chỉnh mức đóng BHYT từ năm 2027 phù hợp lộ trình gắn với tăng tỷ lệ thanh toán phòng bệnh.","explanation":"Nghị quyết 72-NQ/TW định hướng điều chỉnh mức đóng BHYT từ năm 2027 phù hợp lộ trình."},{"id":26,"type":"multiple_choice","question":"Vấn đề chăm sóc sức khỏe tâm thần trong môi trường làm việc và học tập được Nghị quyết 72-NQ/TW nhấn mạnh như thế nào?","options":[{"key":"a","label":"A","text":"Coi nhẹ sức khỏe tâm thần, chỉ tập trung điều trị các tổn thương cơ học bên ngoài.","correct":false},{"key":"b","label":"B","text":"Chú trọng chăm sóc sức khỏe tâm thần, tạo môi trường sống, làm việc, học tập cân bằng, giảm căng thẳng, áp lực.","correct":true},{"key":"c","label":"C","text":"Bắt buộc học sinh, sinh viên tự chi trả toàn bộ viện phí điều trị tâm lý tại bệnh viện tư.","correct":false},{"key":"d","label":"D","text":"Không đưa nội dung tâm lý học đường vào bất kỳ chương trình giáo dục nào.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Chú trọng chăm sóc sức khỏe tâm thần, tạo môi trường sống, làm việc, học tập cân bằng, giảm căng thẳng, áp lực.","explanation":"NQ 72-NQ/TW nhấn mạnh chú trọng chăm sóc sức khỏe tâm thần, xây dựng môi trường lành mạnh, giảm áp lực học tập và làm việc."},{"id":27,"type":"multiple_choice","question":"Nghị quyết 71-NQ/TW định hướng từng bước đưa ngoại ngữ nào trở thành ngôn ngữ thứ hai trong hệ thống giáo dục Việt Nam?","options":[{"key":"a","label":"A","text":"Tiếng Pháp.","correct":false},{"key":"b","label":"B","text":"Tiếng Anh.","correct":true},{"key":"c","label":"C","text":"Tiếng Trung Quốc.","correct":false},{"key":"d","label":"D","text":"Tiếng Nga.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Tiếng Anh.","explanation":"Từng bước đưa tiếng Anh trở thành ngôn ngữ thứ hai trong trường học."},{"id":28,"type":"multiple_choice","question":"Điểm mới về tổ chức và sắp xếp mạng lưới cơ sở giáo dục đại học theo Nghị quyết 71-NQ/TW là gì?","options":[{"key":"a","label":"A","text":"Mỗi huyện phải thành lập ít nhất một trường đại học đa ngành.","correct":false},{"key":"b","label":"B","text":"Chuyển toàn bộ các trường đại học trực thuộc các Bộ về cho tư nhân mua lại.","correct":false},{"key":"c","label":"C","text":"Tăng thêm các tầng nấc quản lý trung gian để siết chặt kỷ luật.","correct":false},{"key":"d","label":"D","text":"Xóa bỏ trung gian, sáp nhập hoặc giải thể trường không đạt chuẩn; nghiên cứu sáp nhập viện nghiên cứu vào trường đại học.","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Xóa bỏ trung gian, sáp nhập hoặc giải thể trường không đạt chuẩn; nghiên cứu sáp nhập viện nghiên cứu vào trường đại học.","explanation":"Mục giải pháp tái cấu trúc giáo dục đại học trong NQ 71-NQ/TW."},{"id":29,"type":"multiple_choice","question":"Theo Nghị quyết 71-NQ/TW phấn đấu đến năm 2030 chính sách nào sau đây đối với sách giáo khoa phổ thông sẽ được thực hiện?","options":[{"key":"a","label":"A","text":"Bán đấu giá sách giáo khoa bản quyền cho nước ngoài.","correct":false},{"key":"b","label":"B","text":"Phấn đấu thực hiện miễn phí sách giáo khoa cho học sinh phổ thông.","correct":true},{"key":"c","label":"C","text":"Bắt buộc học sinh phải mua lại sách mới mỗi năm, cấm dùng lại sách cũ.","correct":false},{"key":"d","label":"D","text":"Bãi bỏ sách giáo khoa giấy để thay bằng 100% video bài giảng tự do.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Phấn đấu thực hiện miễn phí sách giáo khoa cho học sinh phổ thông.","explanation":"NQ 71-NQ/TW xác định cung cấp 1 bộ SGK thống nhất toàn quốc và phấn đấu miễn phí SGK đến năm 2030."},{"id":30,"type":"multiple_choice","question":"Đâu là giải pháp mang tính đột phá về mô hình nhân sự giảng viên được Nghị quyết 71-NQ/TW khuyến khích triển khai?","options":[{"key":"a","label":"A","text":"Chuyển toàn bộ giảng viên cơ hữu sang chế độ hợp đồng thời vụ từng học kỳ.","correct":false},{"key":"b","label":"B","text":"Áp dụng chế độ giảng viên đồng cơ hữu, huy động người giỏi và chuyên gia ngoài ngành tham gia giảng dạy, nghiên cứu.","correct":true},{"key":"c","label":"C","text":"Giảm tỷ lệ giảng viên có trình độ tiến sĩ để tiết kiệm ngân sách chi lương.","correct":false},{"key":"d","label":"D","text":"Cấm tuyệt đối việc kiêm nhiệm, cán bộ ngoài ngành không được tham gia giảng dạy.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Áp dụng chế độ giảng viên đồng cơ hữu, huy động người giỏi và chuyên gia ngoài ngành tham gia giảng dạy, nghiên cứu.","explanation":"Đột phá mô hình nhân sự: Áp dụng chế độ giảng viên đồng cơ hữu, thu hút nhân tài thực tiễn vào giảng dạy."},{"id":31,"type":"multiple_choice","question":"Ba trụ cột số hóa y tế bắt buộc phải hoàn thành kết nối liên thông toàn diện theo Nghị quyết 72-NQ/TW là gì?","options":[{"key":"a","label":"A","text":"Hóa đơn điện tử, thẻ xe buýt điện tử và hộ chiếu vắc-xin tạm thời.","correct":false},{"key":"b","label":"B","text":"Tin nhắn SMS phòng dịch, danh bạ điện thoại và định vị GPS người bệnh.","correct":false},{"key":"c","label":"C","text":"Sổ sức khỏe điện tử, bệnh án điện tử, đơn thuốc điện tử.","correct":true},{"key":"d","label":"D","text":"Sổ hộ khẩu điện tử, căn cước công dân và bằng lái xe số.","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Sổ sức khỏe điện tử, bệnh án điện tử, đơn thuốc điện tử.","explanation":"3 trụ cột chuyển đổi số y tế: Sổ sức khỏe điện tử, bệnh án điện tử, đơn thuốc điện tử."},{"id":32,"type":"multiple_choice","question":"Đâu là định hướng ứng dụng công nghệ mũi nhọn trong y học được Nghị quyết 72-NQ/TW ưu tiên đầu tư nghiên cứu?","options":[{"key":"a","label":"A","text":"Chỉ sử dụng các bài thuốc truyền miệng không kiểm nghiệm lâm sàng.","correct":false},{"key":"b","label":"B","text":"Cấm ứng dụng công nghệ trí tuệ nhân tạo trong xử lý hình ảnh chụp X-quang và MRI.","correct":false},{"key":"c","label":"C","text":"Ứng dụng AI, Big Data, Blockchain, IoT; phát triển công nghệ gen, nano sinh học, y học tái tạo, y học hạt nhân.","correct":true},{"key":"d","label":"D","text":"Nhập khẩu toàn bộ phần mềm chẩn đoán của nước ngoài, không phát triển ứng dụng nội địa.","correct":false}],"answerKey":"c","answerLabel":"C","keyLabel":"C","answerText":"Ứng dụng AI, Big Data, Blockchain, IoT; phát triển công nghệ gen, nano sinh học, y học tái tạo, y học hạt nhân.","explanation":"Đột phá công nghệ y tế: AI, Big Data, Blockchain, IoT, công nghệ gen, nano sinh học, y học tái tạo..."},{"id":33,"type":"multiple_choice","question":"Vấn đề bảo đảm an ninh văn hóa trong hội nhập quốc tế về giáo dục được Nghị quyết 71-NQ/TW quán triệt như thế nào?","options":[{"key":"a","label":"A","text":"Ngừng hoàn toàn việc giảng dạy tiếng Việt cho người nước ngoài.","correct":false},{"key":"b","label":"B","text":"Bảo đảm an ninh văn hóa đối với chương trình có yếu tố nước ngoài; giữ gìn bản sắc và quảng bá văn hóa Việt Nam ra thế giới.","correct":true},{"key":"c","label":"C","text":"Cấm mở phân hiệu các trường đại học Việt Nam ở nước ngoài.","correct":false},{"key":"d","label":"D","text":"Tiếp nhận toàn bộ chương trình giáo dục nước ngoài mà không cần kiểm duyệt nội dung.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Bảo đảm an ninh văn hóa đối với chương trình có yếu tố nước ngoài; giữ gìn bản sắc và quảng bá văn hóa Việt Nam ra thế giới.","explanation":"Hội nhập quốc tế gắn liền bảo vệ an ninh văn hóa và quảng bá giá trị bản sắc Việt Nam."},{"id":34,"type":"multiple_choice","question":"Đến năm 2030, Nghị quyết 71-NQ/TW đặt mục tiêu có bao nhiêu cơ sở giáo dục đại học của Việt Nam thuộc Top 200 châu Á?","options":[{"key":"a","label":"A","text":"Phấn đấu ≥ 8 cơ sở giáo dục đại học thuộc Top 200 châu Á (và ≥ 1 cơ sở thuộc Top 100 thế giới trong một số lĩnh vực).","correct":true},{"key":"b","label":"B","text":"Không đặt mục tiêu xếp hạng theo các tiêu chuẩn quốc tế.","correct":false},{"key":"c","label":"C","text":"Phấn đấu tất cả các trường đại học công lập đều vào Top 200 châu Á.","correct":false},{"key":"d","label":"D","text":"Phấn đấu ít nhất 3 cơ sở.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Phấn đấu ≥ 8 cơ sở giáo dục đại học thuộc Top 200 châu Á (và ≥ 1 cơ sở thuộc Top 100 thế giới trong một số lĩnh vực).","explanation":"Mục tiêu định lượng chuẩn của Nghị quyết 71-NQ/TW đến 2030: ≥ 8 cơ sở lọt Top 200 châu Á và ≥ 1 cơ sở lọt Top 100 thế giới trong một số lĩnh vực."},{"id":35,"type":"multiple_choice","question":"Quan điểm của Đảng trong Nghị quyết 72-NQ/TW xác định “bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân” giữ vị trí nào?","options":[{"key":"a","label":"A","text":"Là trách nhiệm riêng của cá nhân mỗi gia đình, nhà nước không can thiệp chính sách.","correct":false},{"key":"b","label":"B","text":"Là mục tiêu, là động lực, là nhiệm vụ chính trị hàng đầu, giữ vị trí ưu tiên trong các chiến lược, chính sách phát triển.","correct":true},{"key":"c","label":"C","text":"Là một nhiệm vụ phụ trợ kinh tế, chỉ thực hiện khi ngân sách địa phương có thặng dư lớn.","correct":false},{"key":"d","label":"D","text":"Là lĩnh vực thuần túy thương mại tuân theo quy luật cung - cầu thị trường tự do.","correct":false}],"answerKey":"b","answerLabel":"B","keyLabel":"B","answerText":"Là mục tiêu, là động lực, là nhiệm vụ chính trị hàng đầu, giữ vị trí ưu tiên trong các chiến lược, chính sách phát triển.","explanation":"Quan điểm cốt lõi trong Nghị quyết 72-NQ/TW về vai trò của công tác y tế và bảo vệ sức khỏe nhân dân."},{"id":36,"type":"multiple_choice","question":"Sinh viên có thể góp phần thực hiện hiệu quả Nghị quyết 71-NQ/TW thông qua hành động thiết thực nào trong quá trình học tập?","options":[{"key":"a","label":"A","text":"Mua bán tiểu luận, thuê người làm đề tài nghiên cứu khoa học để lấy điểm cao.","correct":false},{"key":"b","label":"B","text":"Thờ ơ với các phong trào đổi mới phương pháp học tập của nhà trường.","correct":false},{"key":"c","label":"C","text":"Chỉ học để đối phó thi cử, thụ động ghi chép và không tham gia các hoạt động ngoại khóa.","correct":false},{"key":"d","label":"D","text":"Rèn luyện văn hóa liêm chính học thuật, chủ động tự học suốt đời, tích cực nghiên cứu khoa học và nâng cao năng lực ngoại ngữ, công nghệ số.","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Rèn luyện văn hóa liêm chính học thuật, chủ động tự học suốt đời, tích cực nghiên cứu khoa học và nâng cao năng lực ngoại ngữ, công nghệ số.","explanation":"Hành động đúng đắn của sinh viên là rèn luyện liêm chính học thuật, nghiên cứu khoa học và nâng cao kỹ năng số."},{"id":37,"type":"multiple_choice","question":"Về cơ cấu hệ thống giáo dục quốc dân, quan điểm của Nghị quyết 71-NQ/TW đối với giáo dục công lập và ngoài công lập là gì?","options":[{"key":"a","label":"A","text":"Giáo dục công lập là trụ cột, giáo dục ngoài công lập là thành phần quan trọng.","correct":true},{"key":"b","label":"B","text":"Xóa bỏ hoàn toàn giáo dục ngoài công lập để quốc hữu hóa 100% trường học.","correct":false},{"key":"c","label":"C","text":"Giáo dục ngoài công lập giữ vị thế độc tôn, giáo dục công lập chỉ dành cho vùng sâu vùng xa.","correct":false},{"key":"d","label":"D","text":"Giáo dục công lập và ngoài công lập hoàn toàn bình đẳng về nguồn tài trợ từ ngân sách nhà nước thường xuyên.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Giáo dục công lập là trụ cột, giáo dục ngoài công lập là thành phần quan trọng.","explanation":"NQ 71-NQ/TW: Giáo dục công lập giữ vai trò trụ cột; giáo dục ngoài công lập là thành phần quan trọng."},{"id":38,"type":"multiple_choice","question":"Nghị quyết 72-NQ/TW quy định mỗi tỉnh, thành phố trực thuộc Trung ương phải bảo đảm cơ sở y tế chuyên sâu nào?","options":[{"key":"a","label":"A","text":"Có ít nhất 1 bệnh viện đạt cấp chuyên sâu; có bệnh viện lão khoa hoặc bệnh viện đa khoa có chuyên khoa lão khoa.","correct":true},{"key":"b","label":"B","text":"Mỗi tỉnh chỉ duy trì 1 trạm xá duy nhất kết hợp quân - dân y.","correct":false},{"key":"c","label":"C","text":"Toàn bộ các bệnh viện tỉnh đều phải chuyển thành trung tâm thẩm mỹ tư nhân.","correct":false},{"key":"d","label":"D","text":"Có ít nhất 5 bệnh viện cấp trung ương trực thuộc Bộ Y tế.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Có ít nhất 1 bệnh viện đạt cấp chuyên sâu; có bệnh viện lão khoa hoặc bệnh viện đa khoa có chuyên khoa lão khoa.","explanation":"Yêu cầu mạng lưới cơ sở y tế chuyên sâu cấp tỉnh/thành phố theo NQ 72-NQ/TW."},{"id":39,"type":"multiple_choice","question":"Chỉ tiêu nào sau đây về nghiên cứu, đổi mới sáng tạo trong các cơ sở giáo dục đại học được xác định cụ thể trong Nghị quyết 71-NQ/TW?","options":[{"key":"a","label":"A","text":"Tăng bình quân 5%/năm về công bố khoa học quốc tế.","correct":false},{"key":"b","label":"B","text":"Chỉ tập trung xuất bản sách giáo khoa trong nước, không bắt buộc công bố quốc tế.","correct":false},{"key":"c","label":"C","text":"Cắt giảm các đề tài nghiên cứu cơ bản để tập trung vào gia công công nghệ.","correct":false},{"key":"d","label":"D","text":"Tăng bình quân 12%/năm đối với công bố khoa học quốc tế và nguồn thu từ KH-CN; tăng 16%/năm đối với đăng ký sáng chế, văn bằng bảo hộ sáng chế.","correct":true}],"answerKey":"d","answerLabel":"D","keyLabel":"D","answerText":"Tăng bình quân 12%/năm đối với công bố khoa học quốc tế và nguồn thu từ KH-CN; tăng 16%/năm đối với đăng ký sáng chế, văn bằng bảo hộ sáng chế.","explanation":"Chỉ tiêu định lượng nghiên cứu & sáng chế của NQ 71-NQ/TW: 12%/năm công bố/thu nhập KH-CN, 16%/năm sáng chế."},{"id":40,"type":"multiple_choice","question":"Mục tiêu chỉ số giáo dục đóng góp vào Chỉ số Phát triển Con người (HDI) của Việt Nam đến năm 2030 theo Nghị quyết 71-NQ/TW là bao nhiêu?","options":[{"key":"a","label":"A","text":"Đạt > 0,8; chỉ số bất bình đẳng giáo dục giảm xuống < 10%","correct":true},{"key":"b","label":"B","text":"Đạt mức trung bình của nhóm các nước có thu nhập thấp.","correct":false},{"key":"c","label":"C","text":"Không đặt ra chỉ tiêu định lượng cụ thể về HDI mà chỉ đánh giá định tính.","correct":false},{"key":"d","label":"D","text":"Đạt trên 0,65; chỉ số bất bình đẳng giáo dục dưới 20%.","correct":false}],"answerKey":"a","answerLabel":"A","keyLabel":"A","answerText":"Đạt > 0,8; chỉ số bất bình đẳng giáo dục giảm xuống < 10%","explanation":"Mục tiêu HDI giáo dục đến 2030: Đạt > 0,8 và chỉ số bình đẳng/bất bình đẳng giáo dục giảm xuống dưới 10%."}],"pdfSize":"302 KB"}]};
